(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["multimodal"]||{};var a=d["papers"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="paper-angelslim-a-more-accessible-comprehe-2026"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-1\">一 · 一条在线请求的真实账本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-2\">二 · 旧方案：三把各自为政的螺丝刀</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-3\">三 · 为什么在 Blackwell 上非改不可</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-4\">四 · 压缩损失的可加性与联合标定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-5\">五 · 插件化边界：把压缩挂在哪一刀上</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-6\">六 · 回退路径必须落在请求入口</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-7\">七 · 在线多模态服务的压缩归因困境</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-8\">八 · 先量清楚请求：输入长度分布与视觉序列的显存账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-9\">九 · 并发、批大小与 SLO：三个互相咬合的旋钮</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-10\">十 · 长尾：为什么 P99 才是容量规划的真锚点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-11\">十一 · 负载塑造方案：压缩组合的入口决策</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-12\">十二 · 可核查的测量口径清单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-13\">十三 · 负载与方案的耦合边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-14\">十四 · 负载形态如何反向锁死压缩组合的可行域</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-15\">十五 · 视觉编码器边界上的精度选择：从 FP16/BF16 到 FP8 的代价账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-16\">十六 · 累加精度：Tensor Core 内部的隐藏误差源</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-17\">十七 · NVFP4 与分块缩放：Blackwell 的微缩放格式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-18\">十八 · tcgen05、TMEM 与 2-SM MMA：指令层的推理形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-19\">十九 · 精度、合并与显存的联合标定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-20\">二十 · 压缩算子挂载点的失效边界与容量代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-21\">二十一 · 显存账本的四个账户：权重、激活、KV、临时缓冲</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-22\">二十二 · 分页与块分配：压缩后长度如何改写分页粒度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-23\">二十三 · 压缩与复用：合并阈值、量化精度与跨层共享</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-24\">二十四 · 卸载：把哪一部分挪出 HBM，代价记在谁头上</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-25\">二十五 · 带宽瓶颈定位：HBM3e 容量与带宽的除法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-26\">二十六 · 可复算的显存预算：从档位到并发数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-27\">二十七 · 压缩组合的失效边界与显存账本复算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-28\">二十八 · 连续批处理在视觉序列长度不均时的调度代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-29\">二十九 · chunked prefill 与视觉编码器前向的切分边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-30\">三十 · 优先级、抢占与压缩组合的回退路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-31\">三十一 · 分离式预填/解码与视觉编码器的放置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-32\">三十二 · 尾延迟的压法：长度分档、块大小与组合切换的联合标定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-33\">三十三 · 切分维度：从视觉序列到解码层的并行拓扑</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-34\">三十四 · NVLink 5 与 NVSwitch：域内通信的带宽账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-35\">三十五 · 通信何时成为瓶颈：三个可判定的条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-36\">三十六 · 压缩组合与并行配置的联合标定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-37\">三十七 · 失败模式与监控落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-38\">三十八 · 压缩组合与并行拓扑的耦合边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-39\">三十九 · 精度塌陷的归因链：从 KL 项到视觉重建误差</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-40\">四十 · OOM 的三条路径与显存账本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-41\">四十一 · 批抖动与尾延迟：调度层的可观测性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-42\">四十二 · 静默降级：接口一致性的双刃剑</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-43\">四十三 · 回滚路径与诊断闭环</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-44\">四十四 · 口径先于数字：AngelSlim 的测量坐标系</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-45\">四十五 · 硬件档位与 batch：容量第一约束来自视觉序列长度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-46\">四十六 · 指标怎么读：TTFT、TPOT、吞吐、显存、功耗各自归谁</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-47\">四十七 · 哪些提升不可比：四类典型陷阱</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-48\">四十八 · 可核验的读法：把基准写成可回放的配置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-49\">四十九 · 基准口径与不可比边界：压缩收益怎么读</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-50\">五十 · 迁移到新视觉骨干：压缩插件的挂载点会变，误差项权重必须重标</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-51\">五十一 · 跨领域迁移：视频与长序列是容量约束的真正上限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-52\">五十二 · 跨模态注意力近似的适用边界：对齐层不是任意层</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-53\">五十三 · 规模上限：三处硬约束决定这套方案能走多远</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-54\">五十四 · 迁移检查清单与不可迁移的部分</button></li></ol></nav><figure class=\"diagram\" data-fig=\"paper-pipeline\"><svg style=\"max-width:549px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 549.0 423\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"467.0\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">图像或视频输入经预处理归一化并切分为 patch 序列，形成视觉编码器…</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"467.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">视觉编码器在指定数值精度下前向，输出逐 patch 视觉特征序列。</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"467.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">token 压缩与合并模块按相似度或重要性裁剪视觉序列，降低后续注意力…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"467.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">跨模态注意力层将压缩后视觉 token 与文本 token 对齐，近似…</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"467.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">语言解码阶段按批调度执行，KV cache 按压缩后序列长度分配显存。</text><line x1=\"82.0\" y1=\"342.2\" x2=\"82.0\" y2=\"359.2\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 358.2 L 86.5 358.2 L 82.0 366.2 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"366.2\" width=\"467.0\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"388.7\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"392.9\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">6</text><text x=\"75.0\" y=\"393.9\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">服务层按 SLO 选择压缩组合，并输出延迟与显存监控指标。</text></svg><figcaption><b>流水线</b> · 从输入到输出的数据流；每一步的模块与代价在正文展开。</figcaption></figure>\n<h3 id=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-1\">一 · 一条在线请求的真实账本</h3>\n<p>设想一个跑在 GB200 NVL72 上的多模态客服服务：用户上传一张带表格的截图，问“第三行第二列的数字是多少”。请求进入服务后，预处理把图像切成 patch 序列，视觉编码器前向，视觉 token 与文本 token 在跨模态注意力层对齐，语言解码按连续批处理逐 token 吐出。这条链路里，真正决定成本的不是解码，而是前面那段“看不见”的部分：一张高分辨率截图在视觉编码器里展开成数千个 patch token，这些 token 全部要进跨模态注意力，全部要在 KV cache 里占位。</p>\n<p>工程上这笔账可以写得很直白。设视觉序列长度为 <span class=\"inline-math\">N_v</span>、批大小为 <span class=\"inline-math\">B</span>、每 token 每层 KV 占 <span class=\"inline-math\">s</span> 字节、层数 <span class=\"inline-math\">L</span>，则仅视觉部分的 KV cache 容量为：</p>\n<div class=\"formula\">$$M_{\\mathrm{kv}}^{\\mathrm{vis}} = B \\cdot N_v \\cdot L \\cdot s \\cdot 2$$</div>\n<p>其中因子 2 对应 K 与 V 两份。视觉编码器的前向计算量则随 patch 数近似线性增长，跨模态注意力的注意力矩阵随 <span class=\"inline-math\">\\(N_v \\cdot N_t\\)</span> 增长。也就是说，分辨率翻倍，视觉 token 数大致翻四倍，显存与注意力负载同步抬升，而语言解码侧的收益完全跟不上这个增速。在 Blackwell 上，tcgen05 与 2-SM MMA 把矩阵乘的吞吐推得很高，反而让“喂给 MMA 的 token 太多”成为新的瓶颈——算力不再是稀缺项，序列长度与显存带宽成了稀缺项。</p>\n<p>这就是问题现场：多模态推理同时被视觉编码器计算、视觉 token 数量与量化误差三重约束夹住，而工程团队手里没有一把能同时拧这三颗螺丝的扳手。</p>\n\n<h3 id=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-2\">二 · 旧方案：三把各自为政的螺丝刀</h3>\n<p>在 AngelSlim 这类统一工具链出现之前，主流做法是按压缩手段分头处理，每条路径都有自己的脚本、自己的校准流程、自己的接口约定。</p>\n<p>第一把是量化。纯文本 LLM 的量化工具链已经相当成熟，权重与激活的精度选择、校准集构造、逐层敏感度分析都有现成实现。但把这些工具直接套到多模态模型上时，视觉编码器往往被当成一个黑盒整体处理，或者干脆保持高精度不动——因为视觉特征的动态范围与文本激活差异明显，沿用文本校准集估出来的缩放因子会系统性偏移。结果是解码器被压到 FP8 甚至 NVFP4，视觉编码器却仍跑在更高精度上，端到端延迟收益被视觉侧吃掉大半。</p>\n<p>第二把是 token 压缩。视觉 token 合并、剪枝、相似度聚类这类方法在视觉侧独立演进，通常以“在某个 VLM 上把 token 数砍掉多少、精度掉多少”的形式报告。问题是这些方法挂在模型内部的某个固定位置，换一个模型就要重写一遍融合逻辑；而且合并强度与量化精度之间没有联合标定，单独调合并阈值时看着收益不错，一旦叠加量化，视觉特征重建误差被放大，输出分布偏移超出预期。</p>\n<p>第三把是跨模态注意力近似。低秩分解、稀疏注意力、对齐层裁剪各自有实现，但都作用在对齐层内部，改动往往要求同步修改模型定义，压缩前后接口不一致，部署侧无法在不改推理图的前提下替换。</p>\n<p>三把螺丝刀合起来的代价是可归因性丧失。一个请求延迟变长了，究竟是视觉编码器精度选低了导致重算、token 合并阈值过紧导致合并开销反超收益、还是注意力近似引入了额外校正，工程上说不清。每加一个模型，就要重写一套压缩脚本，重复成本随模型数量线性增长。</p>\n\n<h3 id=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-3\">三 · 为什么在 Blackwell 上非改不可</h3>\n<p>Blackwell 的硬件特性把上述痛点从“不方便”推到了“不可接受”。SM100/SM103 的 tcgen05 与 TMEM 设计让 MMA 吞吐大幅提升，NVFP4 这类低精度格式在硬件上有了原生支持，理论上限很高。但硬件能力要兑现成端到端收益，前提是喂进去的负载形状匹配：视觉 token 序列过长时，跨模态注意力的 softmax 与 KV 读写会把时间花在非 MMA 路径上，低精度 MMA 的高吞吐被内存带宽稀释。</p>\n<p>更具体地说，视觉编码器与语言解码器在数值特性上并不相同。视觉编码器的激活分布随图像内容剧烈变化，一张白底表格与一张自然场景图的特征动态范围差异很大；解码器的激活则相对平稳。用同一套量化配置覆盖两者，必然在其中一侧过度保守。AngelSlim 的材料明确把“视觉编码器量化”与“解码器精度”分开设定，正是针对这一点。</p>\n<p>显存侧的约束同样刚性。GB200 NVL72 的单机显存总量可观，但多模态服务的并发请求里，长视频请求的视觉序列长度随帧数线性增长，KV cache 随之膨胀。若不按帧采样控制序列长度、不把长视频请求单独成批，一个长请求就能把整批短请求的显存预算挤爆。这不是靠增加卡数能解决的问题，因为批调度与 KV 分配策略本身没有压缩入口。</p>\n\n<h3 id=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-4\">四 · 压缩损失的可加性与联合标定</h3>\n<p>旧方案的另一处结构性缺陷，是把三类压缩当成互不相干的独立优化。实际上它们的误差是叠加并相互放大的。AngelSlim 给出的压缩损失把三项加权写在一起：</p>\n<div class=\"formula\">$$\\mathcal{L}_{\\mathrm{comp}}=\\lambda_{1}\\|W-\\hat{W}\\|_{2}^{2}+\\lambda_{2}\\sum_{i}\\left\\|f_{v}(x_{i})-\\hat{f}_{v}(x_{i})\\right\\|_{2}^{2}+\\lambda_{3}\\,\\mathrm{KL}\\left(p_{\\theta}(y\\mid v,t)\\,\\|\\,p_{\\hat{\\theta}}(y\\mid \\hat{v},t)\\right)$$</div>\n<p>第一项是权重量化误差，第二项是视觉特征重建误差，第三项是压缩前后输出分布的 KL 散度。这个式子的工程含义是：三项不能分开调。把 <span class=\"inline-math\">\\(\\lambda_2\\)</span> 对应的合并阈值放松，视觉特征重建误差上升，会通过跨模态注意力传导到 <span class=\"inline-math\">\\(\\lambda_3\\)</span> 项；而量化精度降低又会改变 <span class=\"inline-math\">f_v</span> 的数值尺度，使原本标定好的相似度阈值失效。单独调优任一项，都会高估收益。</p>\n<p>代价体现在部署侧就是“收益不可归因”。假设一个团队把视觉 token 砍掉一半、编码器量化到 FP8，端到端吞吐提升有限，他们无法判断是合并阈值过紧导致合并本身的排序开销吃掉了收益，还是量化误差迫使解码器在某些请求上走了回退路径。没有统一的损失与记录机制，每次调参都是一次盲试。</p>\n\n<h3 id=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-5\">五 · 插件化边界：把压缩挂在哪一刀上</h3>\n<p>AngelSlim 的结构回答的是“挂在哪”的问题。工具链把多模态推理路径切成五段：输入预处理、视觉编码器、token 压缩与合并、跨模态注意力、语言解码。压缩算子以插件形式挂在各段边界上，量化作用于权重与激活，token 合并作用于视觉序列，跨模态注意力近似作用于对齐层，而输出接口与未压缩模型保持一致。</p>\n<p>这个设计的直接工程后果是：压缩后序列长度成为部署容量的第一约束。视觉 token 合并挂在视觉编码器输出边界，合并后的 <span class=\"inline-math\">N_v</span> 直接决定跨模态注意力负载与 KV cache 分配量，也就是第一节那条显存公式里的 <span class=\"inline-math\">N_v</span>。部署侧按压缩后长度分配 KV 块，长视频请求预留更大显存块，短请求按压缩后长度紧凑排布。</p>\n<p>插件化还带来一个容易被忽视的代价：合并本身有开销。按相似度阈值裁剪序列需要先算相似度、排序、再裁剪，这部分计算在序列较短时不划算。阈值过紧，压缩收益不足以抵消合并开销；阈值过松，细粒度视觉信息丢失，表格里的小数字可能正好在被合并掉的那批 token 里。这个权衡没有解析解，只能在目标硬件档位上实测标定。</p>\n\n<h3 id=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-6\">六 · 回退路径必须落在请求入口</h3>\n<p>线上服务不能假设离线标定的组合永远成立。流量结构变化、图像分辨率分布漂移、长视频请求比例上升，都会让某个压缩组合超出 SLO 延迟预算。AngelSlim 的做法是按 SLO 预算选择组合，超预算时回退保守组合，并且回退必须在请求入口完成。</p>\n<p>这条约束的机制原因很硬：解码中途切换压缩组合会破坏 KV cache 一致性。KV cache 是按压缩后序列长度分配的，若解码到一半把视觉 token 合并强度改掉，已经写入的 KV 与新的序列长度对不上，缓存要么作废重算，要么读出错位的键值。因此组合切换只能在请求进入服务、尚未分配 KV 之前决定，请求一旦进入解码阶段就锁定组合。</p>\n<p>工程判断落在监控上：每个请求采集延迟与显存占用，超预算触发回退，回退事件本身要记录组合标识，否则归因链条又断了。这与第三节的显存约束形成闭环——长视频请求单独成批、按帧采样控制序列长度、按压缩后长度分配 KV，三者共同决定单卡能承载多少并发。工具链把这些决策点收进同一套接口，使视觉编码器延迟、视觉 token 显存与量化误差可以在一条流水线上分别计量，而不是靠三份互不相通的日志拼凑。</p>\n\n<h3 id=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-7\">七 · 在线多模态服务的压缩归因困境</h3>\n<p>设想一个面向 B200 集群的图文问答服务：请求入口同时收到单图问答与多帧视频描述，视觉编码器把图像切成 patch 序列，序列长度随分辨率与帧数增长。旧做法是每个模型自带一套压缩脚本——视觉编码器量化一个仓库、token 合并另一个脚本、跨模态注意力近似再改一处代码，三者各自为政。部署侧看到的只是端到端延迟与显存曲线，无法判断收益来自哪一步：把视觉序列从长裁短确实压低了 KV cache 占用，但量化引入的特征重建误差又抬高了重试率，两者在监控上互相抵消，容量规划只能靠反复试跑。这种归因断裂正是工具链要解决的边界问题。</p>\n<p>代价可以写成一条容量约束：压缩后视觉序列长度 $L_v'$ 直接决定跨模态注意力负载与 KV cache 显存，$M_{\\mathrm{kv}} \\approx b \\cdot L_v' \\cdot d \\cdot s$（$b$ 为批大小，$d$ 为头维展开后的每 token 字节数，$s$ 为层数）。合并阈值放松一档，$L_v'$ 下降、显存让出，但细粒度视觉信息损失传导到输出分布；阈值收紧，合并开销又抵消收益。量化精度与合并强度必须联合标定，单独调优任一维度都会高估收益——这是旧方案最典型的失效条件。</p>\n<p>工具链的边界同样清晰：压缩组合按 SLO 延迟预算在请求入口选定，超预算即回退保守组合；若在解码中途切换，KV cache 与已生成的注意力状态不一致，回退路径必须前置。视频请求按帧采样控制序列长度并单独成批，否则长视频的 KV cache 随帧数线性膨胀，拖累同批短请求。跨模态注意力近似的误差边界材料未给出实测结论，部署时只能以输出分布 KL 作为代理监控，不能假定近似无损。</p>\n<table class=\"mini\"><thead><tr><th>压缩步骤</th><th>挂载边界</th><th>主要系统代价</th><th>失效条件</th></tr></thead><tbody><tr><td>视觉 token 合并</td><td>编码器输出</td><td>KV cache 显存、注意力负载</td><td>阈值过松损失细粒度信息</td></tr><tr><td>编码器量化</td><td>权重与激活</td><td>特征重建误差、重试率</td><td>与合并强度未联合标定</td></tr><tr><td>注意力近似</td><td>对齐层</td><td>输出分布偏移</td><td>误差传导至解码且无实测边界</td></tr></tbody></table>\n<h3 id=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-8\">八 · 先量清楚请求：输入长度分布与视觉序列的显存账</h3>\n<p>在多模态服务里，“请求”不是一个标量，而是一个二元组：图像或视频经预处理后切出的 patch 序列长度 <em>L<sub>v</sub></em>，以及文本侧提示与生成长度 <em>L<sub>t</sub></em>。AngelSlim 的压缩入口挂在视觉编码器输出边界，token 合并模块按相似度阈值裁剪序列，因此压缩后的 <em>L̂<sub>v</sub></em> 才是真正进入跨模态注意力与 KV cache 的长度。容量规划的第一笔账必须按压缩后长度算，而不是按原始分辨率算。</p>\n<p>可核查的测量口径是：在请求入口记录原始 patch 数、合并后 token 数、合并耗时，以及该请求在解码阶段实际占用的 KV 字节数。对每个请求，KV 显存可写成</p>\n<div class=\"formula\">$$M_{\\mathrm{kv}} \\approx 2 \\cdot n_{\\mathrm{layers}} \\cdot d_{\\mathrm{head}} \\cdot n_{\\mathrm{kv}} \\cdot (\\hat{L}_{v} + L_{t} + L_{\\mathrm{gen}}) \\cdot b_{\\mathrm{bytes}}$$</div>\n<p>其中 <em>n<sub>kv</sub></em> 是 KV 头数，<em>b<sub>bytes</sub></em> 是每元素字节数（FP8 与 NVFP4 下不同）。这个式子说明：视觉 token 压缩对显存的边际收益是线性的，而量化精度的收益也是线性的——两者在同一流水线上可加性归因，正是工具链把合并与量化收进同一入口的工程理由。举例：一个 4K 图像切成数千 patch，若合并阈值把序列压到原来的几分之一，KV 占用随之下降同一比例；但若阈值过紧，合并开销本身会吃掉延迟预算，收益不足以抵消。</p>\n<p>测量上必须区分“请求级”与“批级”。请求级记录 <em>L̂<sub>v</sub></em> 的分布（分位数 P50/P90/P99），批级记录批内最大 <em>L̂<sub>v</sub></em> 与批内方差。批级最大长度决定该批的 KV 预留块大小，方差决定 padding 浪费。长尾请求——少数超长视频——会把批级最大长度拉高，从而让整批的显存预留被一个请求绑架，这是负载塑造方案的第一条硬约束。</p>\n\n<h3 id=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-9\">九 · 并发、批大小与 SLO：三个互相咬合的旋钮</h3>\n<p>并发数 <em>C</em>、批大小 <em>B</em>、SLO 延迟预算 <em>T<sub>slo</sub></em> 不是独立可调的。对解码阶段，单 token 步进时间可粗略分解为</p>\n<div class=\"formula\">$$T_{\\mathrm{step}} \\approx \\max\\left(\\frac{W_{\\mathrm{bytes}}}{BW_{\\mathrm{eff}}},\\; \\frac{F_{\\mathrm{flops}}}{P_{\\mathrm{eff}}}\\right) + T_{\\mathrm{comm}}$$</div>\n<p>其中 <em>W<sub>bytes</sub></em> 是该步需要搬运的权重与 KV 字节，<em>BW<sub>eff</sub></em> 是有效带宽，<em>T<sub>comm</sub></em> 是并行通信开销。批大小增大时，权重搬运被摊薄，吞吐上升，但每请求的排队延迟与 KV 显存同步上升；并发超过显存容量时，调度器只能排队或抢占，SLO 尾部直接崩。</p>\n<p>因此工程上要把 SLO 写成可判定的形式：以 P99 首 token 延迟（TTFT）与 P99 每输出 token 时间（TPOT）为约束，反解出可行的 (<em>B</em>, <em>C</em>) 区域。AngelSlim 的做法是把压缩组合的选择绑到 SLO 预算上：入口处按请求的 <em>L̂<sub>v</sub></em> 与当前队列深度选组合，超预算回退保守组合。这里的代价是回退路径必须在请求入口完成——解码中途切换会破坏 KV cache 一致性，因为已分配的块长度与新组合的序列长度不匹配。</p>\n<p>具体例子：短请求（低分辨率图像、短提示）与长视频请求混在同一批时，长视频把批级最大长度抬高，短请求被迫按大块预留显存，吞吐被拖累。可核查口径是统计“批内长度方差 / 批级最大长度”这一比值，比值高说明混批效率低，应触发按长度分桶或长视频单独成批。这不是定性建议，而是可从监控指标直接算出的调度判据。</p>\n\n<h3 id=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-10\">十 · 长尾：为什么 P99 才是容量规划的真锚点</h3>\n<p>多模态负载的长度分布是重尾的：分辨率、帧数、文本提示长度三者相乘，尾部可以比中位数高一个数量级以上。容量规划若按均值算，会在尾部请求上出现显存溢出或 SLO 违约。正确的口径是按分位数做容量反解：给定 P99 的 <em>L̂<sub>v</sub></em> 与 P99 的生成长度，算出单请求 KV 峰值，再除以单卡可用显存，得到该档位下的最大并发。</p>\n<p>长尾还以另一种方式塑造方案：视频输入的帧采样策略直接决定 <em>L<sub>v</sub></em> 随帧数的增长斜率。若不做帧采样控制，KV cache 随帧数线性膨胀，长视频请求单独成批只是把问题隔离，不是解决。工具链在此处的机制是“按帧采样控制序列长度 + 合并阈值裁剪”，两级压缩叠加，使长视频的 <em>L̂<sub>v</sub></em> 增长被压到可控斜率。代价是帧采样丢失时间分辨率、合并丢失空间细节，两者都传导到输出分布——这正是压缩损失函数里 KL 项存在的理由。</p>\n<p>可核查的测量口径：对长尾请求单独打标，记录其 <em>L̂<sub>v</sub></em>、合并阈值、量化精度档位、实际 TTFT 与 TPOT，并与同档位短请求对比。若长尾请求的 TPOT 显著高于短请求，说明批调度未有效隔离，或 KV 预留块过大导致带宽浪费。这一对比不需要基线系统，只需同档位内部对照，符合材料未给基线的事实约束。</p>\n\n<h3 id=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-11\">十一 · 负载塑造方案：压缩组合的入口决策</h3>\n<p>反过来，方案也限制负载。AngelSlim 按硬件档位（B200、B300、GB200 NVL72）离线选定候选压缩组合，线上按 SLO 切换。这意味着服务能接受的请求形态被组合集合预先框定：某个档位若只标定了保守组合，则超长视频请求要么被拒绝、要么被降采样、要么排队等待。负载形态不是外生给定的，而是与可用组合集合共同演化。</p>\n<p>入口决策的逻辑可写成伪代码思路：读取请求的原始 patch 数与帧数，估算 <em>L<sub>v</sub></em>；查当前档位的组合表，按队列深度与 SLO 余量选组合；若估算的 KV 峰值超过该组合的预留上限，回退到更激进的合并阈值或更低精度；记录所选组合与预估指标，供离线回放校准。关键点是决策发生在预处理之后、编码器之前，因为 <em>L<sub>v</sub></em> 只有在切 patch 后才可知。</p>\n<p>代价在于：入口决策引入额外延迟（估算与查表），且组合切换的粒度受批调度约束——同一批内不同请求若选不同组合，跨模态注意力层的序列长度不一致，批处理失效。因此工程判断是：组合选择应按批而非按请求，或在入口按组合分桶排队。这与“长视频单独成批”是同一条调度原则的两个应用。</p>\n\n<h3 id=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-12\">十二 · 可核查的测量口径清单</h3>\n<p>材料未给出数据集、基线、吞吐与精度数字，因此本部分的测量口径只定义“测什么、怎么算”，不预设数值。以下清单可直接落到监控埋点：</p>\n<table class=\"mini\"><thead><tr><th>指标</th><th>口径</th><th>用途</th></tr></thead><tbody>\n<tr><td>原始 patch 数 / 合并后 token 数</td><td>请求级，记录比值与合并耗时</td><td>归因合并收益与开销</td></tr>\n<tr><td>KV 峰值字节</td><td>按压缩后长度与精度档位计算，请求级</td><td>容量反解、批级预留</td></tr>\n<tr><td>批内长度方差 / 批级最大长度</td><td>批级</td><td>判断混批效率、触发分桶</td></tr>\n<tr><td>P99 TTFT / P99 TPOT</td><td>按档位与组合分组</td><td>SLO 违约定位</td></tr>\n<tr><td>回退次数与回退原因</td><td>入口处计数</td><td>组合表校准</td></tr>\n<tr><td>长尾请求 TPOT 与短请求 TPOT 之比</td><td>同档位对照</td><td>验证隔离策略有效性</td></tr>\n</tbody></table>\n<p>这些指标的共同要求是“按组合分组”。因为压缩组合是变量，不分组则收益无法归因——这正是工具链把量化、合并、注意力近似做成可独立启停插件的直接动机。举例：若某档位下合并阈值调松后 P99 TPOT 下降但 KL 项上升，分组数据能立刻显示这是合并收益还是量化误差传导，而不需要重跑整条流水线。</p>\n\n<h3 id=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-13\">十三 · 负载与方案的耦合边界</h3>\n<p>最后落在工程判断上：负载形态与压缩方案之间存在双向约束，可核查的边界是“组合表 + 分桶策略”这一对配置。组合表决定单请求的显存与延迟下界，分桶策略决定批级效率上界。二者若不同步更新，会出现监控指标看似正常但 SLO 尾部持续违约的情况——因为尾部请求被分到不匹配的组合，或被迫与不匹配的批共槽。</p>\n<p>因此每次档位切换或组合表更新，都应重放一段带标注的请求轨迹（含原始 patch 数、帧数、生成长度），核对 P99 指标与回退率是否在预算内。这不是一次性标定，而是随负载漂移持续校准的闭环。工具链的插件化挂载使这一闭环可行：量化、合并、注意力近似可独立启停，回放时逐项开关即可定位是哪一类压缩在特定负载形态下越过了预算边界。</p>\n\n<h3 id=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-14\">十四 · 负载形态如何反向锁死压缩组合的可行域</h3>\n<p>在 AngelSlim 的部署路径上，请求形态不是被动输入，而是压缩组合可行域的硬约束。视觉 token 压缩挂在视觉编码器输出边界，压缩后的序列长度 <em>L<sub>v</sub></em> 直接决定跨模态注意力与 KV cache 的显存占用，因此容量规划的第一约束不是权重，而是 <em>L<sub>v</sub></em>。给定并发 <em>C</em>、每请求视觉序列长度 <em>L<sub>v</sub></em>、解码侧 KV 头数与层数，单卡可容纳的并发上限近似为 <em>C<sub>max</sub></em> ≈ (<em>M<sub>free</sub></em> − <em>M<sub>w</sub></em>) / (<em>L<sub>v</sub></em> · <em>k</em><sub>v</sub> + <em>L<sub>t</sub></em> · <em>k</em><sub>t</sub>)，其中 <em>k</em><sub>v</sub>、<em>k</em><sub>t</sub> 为视觉与文本每 token 的 KV 字节数，<em>M<sub>w</sub></em> 为量化后权重占用。这个式子说明：合并阈值放松一档、<em>L<sub>v</sub></em> 减半，并发上限可近似翻倍；但阈值放松同时抬高视觉特征重建误差，进而抬升 KL 项，压缩收益与精度损失在同一根轴上拉扯。工程上必须把阈值与量化精度联合标定，单独调优任一项都会高估收益。</p>\n<p>输入长度分布的长尾决定批调度策略。图像请求的 patch 数随分辨率增长，视频请求的序列长度随帧采样线性膨胀，长视频若与短请求混批，KV cache 峰值按最长请求分配，短请求被迫等待，尾延迟被拖垮。可核查的口径是：按请求入口记录视觉 patch 数、压缩后 <em>L<sub>v</sub></em>、文本长度 <em>L<sub>t</sub></em>，以 P50/P99 分位统计序列长度分布；以每请求首 token 延迟（TTFT）与每输出 token 间隔（ITL）分别度量预填与解码代价；以每请求峰值显存与压缩组合标签做交叉归因。长视频请求应单独成批，避免 KV cache 随帧数线性膨胀污染短请求批的 SLO。</p>\n<p>压缩组合的切换必须在请求入口完成。解码中途切换会破坏 KV cache 一致性——已分配的块按旧 <em>L<sub>v</sub></em> 布局，新组合的序列长度对不上，只能整请求重算。因此回退路径是入口级决策：入口按当前 SLO 延迟预算与队列深度选择组合，若某组合的实测 TTFT 或 ITL 超出预算，回退到保守组合（更弱合并、更高精度），代价是显存占用上升、并发上限下降。这条回退链本身有系统代价：保守组合下 <em>L<sub>v</sub></em> 变大，<em>C<sub>max</sub></em> 下降，吞吐随之收缩，形成“延迟达标但容量不足”的次生失效。</p>\n<table class=\"mini\"><thead><tr><th>负载特征</th><th>对压缩组合的约束</th><th>失效条件</th></tr></thead><tbody><tr><td>高分辨率图像、patch 数大</td><td>合并阈值需收紧以压 <em>L<sub>v</sub></em></td><td>阈值过紧，合并开销抵消收益</td></tr><tr><td>长视频、帧数多</td><td>帧采样 + 单独成批</td><td>混批导致 KV 峰值按最长请求分配</td></tr><tr><td>高并发短请求</td><td>弱合并、高精度保 ITL</td><td>保守组合下 <em>C<sub>max</sub></em> 不足</td></tr><tr><td>尾延迟敏感 SLO</td><td>入口级组合切换</td><td>解码中途切换破坏 KV 一致性</td></tr></tbody></table>\n<p>跨模态注意力近似的误差会传导到解码输出分布，其边界无法从负载形态反推，只能靠线上 KL 监控与离线校准数据共同约束。材料未给出该近似的精度损失边界，也未给出视频长序列的批调度与 KV 策略细节，因此任何容量数字都必须以部署档位实测为准。可操作的工程判断是：把 <em>L<sub>v</sub></em> 分布、TTFT/ITL 分位、每请求峰值显存与组合标签作为四个必采口径，先固定量化精度再扫合并阈值，观察 <em>C<sub>max</sub></em> 与 KL 的联合曲线，而不是分别调优后相加收益。</p>\n<h3 id=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-15\">十五 · 视觉编码器边界上的精度选择：从 FP16/BF16 到 FP8 的代价账</h3>\n<p>AngelSlim 把量化算子挂在视觉编码器边界，权重与激活分别设定精度，因此“选哪种数据类型”不是全局开关，而是逐段决策。FP16 提供 10 位尾数，BF16 只有 7 位但动态范围与 FP32 同阶，二者在视觉编码器上的差别不在乘加吞吐，而在激活分布尾部：ViT 的 LayerNorm 输出与注意力 softmax 前的 logits 容易出现大幅值离群点，BF16 的宽指数能容纳它们而不溢出，代价是尾数精度下降带来的特征重建误差。FP8 分 E4M3 与 E5M2 两种编码，E4M3 尾数多一位、动态范围窄，适合权重与 LayerNorm 后激活；E5M2 范围宽、精度低，通常留给梯度类或极端离群场景。工程判断是：视觉编码器权重量化到 FP8-E4M3、激活保留 BF16 或 FP8-E4M3，是 Blackwell 上较稳的起点；把激活也压到 E5M2 会放大视觉特征重建误差，而这一误差会经跨模态注意力传导到解码输出分布。</p>\n<p>量化误差可写成逐张量的仿射映射与舍入残差：</p>\n<div class=\"formula\">$$\\hat{W}=\\mathrm{clip}\\left(\\mathrm{round}\\left(\\frac{W}{s}\\right)+z,\\ q_{\\min},q_{\\max}\\right)\\cdot s,\\qquad \\varepsilon_{W}=\\|W-\\hat{W}\\|_{2}^{2}$$</div>\n<p>其中 $s$ 为缩放因子、$z$ 为零点、$q_{\\min}/q_{\\max}$ 由数据类型决定（FP8-E4M3 的有效表示范围远小于 FP16）。AngelSlim 的压缩损失第一项 $\\lambda_1\\|W-\\hat{W}\\|_2^2$ 正是这个 $\\varepsilon_W$ 的加权形式，校准数据驱动 $s$ 的搜索。代价侧：FP8 相对 BF16 把视觉编码器权重显存减半，激活带宽同步下降，编码器前向的 HBM 读取量随之减少；但若校准不充分，$s$ 被离群点拉大，有效位数进一步损失，特征重建误差上升，token 合并阈值就不得不收紧以补偿，压缩收益被抵消。</p>\n<p>具体例子：一个以 448×448 输入切 patch 的视觉编码器，patch 序列长度随分辨率线性增长；把编码器权重从 BF16 换到 FP8-E4M3 后，权重驻留显存下降，但若某层激活存在跨通道离群点而未做逐通道缩放，该层输出与未量化版本的余弦相似度会明显下滑，下游跨模态注意力不得不依赖更多视觉 token 才能维持对齐——这与 token 压缩的目标直接冲突。因此量化精度与合并强度必须联合标定，单独调优任一项都会高估收益。</p>\n\n<h3 id=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-16\">十六 · 累加精度：Tensor Core 内部的隐藏误差源</h3>\n<p>低精度乘法不等于低精度结果，累加器的位宽决定误差是否被放大。Blackwell 第五代 Tensor Core 在 FP8 与 NVFP4 路径上以更高位宽的累加器汇总部分积，矩阵乘的数值行为可写成：</p>\n<div class=\"formula\">$$C_{ij}=\\mathrm{acc}\\left(\\sum_{k=1}^{K}A_{ik}B_{kj}\\right),\\qquad \\mathrm{acc}\\in\\{\\text{FP32 累加},\\ \\text{分块 FP32 累加}\\}$$</div>\n<p>逐项解释：$A_{ik}$ 与 $B_{kj}$ 是低精度输入（FP8 或 NVFP4 的量化值），乘积在 Tensor Core 内以定点或浮点方式生成，$\\mathrm{acc}(\\cdot)$ 表示按 $K$ 维归约时的累加策略。若累加器为 FP32，$K$ 较大时仍会因多次舍入累积误差；分块累加（把 $K$ 切成若干段，段内用更高精度、段间再归约）能压低这一误差，但引入额外寄存器与指令开销。视觉编码器的注意力 $QK^\\top$ 与 MLP 展开都是大 $K$ 归约，累加精度直接决定 logits 的尾部是否失真——softmax 对 logits 的绝对误差敏感，尾部分布偏移会改变注意力权重分配。</p>\n<p>系统代价：提高累加精度意味着 Tensor Core 流水线中更多 FP32 寄存器占用与更长的归约链，单次 MMA 的有效吞吐下降；在视觉编码器这种计算密集段，吞吐损失可被 token 压缩带来的序列缩短部分抵消，但在跨模态注意力层，$K$ 维是视觉 token 数，压缩后 $K$ 变小，累加误差的绝对量下降而相对开销上升。工程上应把高累加精度留给对 logits 敏感的注意力打分，把较低累加精度留给对误差不敏感的投影层，按层分配而非全局统一。</p>\n<p>具体例子：跨模态注意力层中视觉 token 被合并到较短序列后，$QK^\\top$ 的 $K$ 维缩小，同样的 FP32 累加开销占比更高；若此时为省延迟改用低精度累加，注意力权重分布偏移会直接反映为对齐层输出的 KL 散度上升，即压缩损失第三项 $\\lambda_3\\mathrm{KL}(p_\\theta\\|p_{\\hat\\theta})$ 变大。这说明累加精度不是孤立调参，而是与 token 合并强度耦合的变量。</p>\n\n<h3 id=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-17\">十七 · NVFP4 与分块缩放：Blackwell 的微缩放格式</h3>\n<p>NVFP4 是 Blackwell 上面向权重与激活的 4 位浮点格式，其可用性依赖分块缩放（block scaling）：每个小块共享一个缩放因子，块内元素以 4 位尾数表示。可写成：</p>\n<div class=\"formula\">$$\\hat{x}_{i}=s_{b(i)}\\cdot\\mathrm{fp4}\\left(\\frac{x_{i}}{s_{b(i)}}\\right),\\qquad s_{b}=\\frac{\\max_{i\\in b}|x_{i}|}{q_{\\max}^{\\mathrm{fp4}}}$$</div>\n<p>逐项解释：$b(i)$ 是元素 $i$ 所属的缩放块，$s_b$ 由块内最大幅值决定，$\\mathrm{fp4}(\\cdot)$ 是 4 位编码的舍入。块越小，缩放因子越贴合局部动态范围，量化误差越小，但元数据（每块的 $s_b$）占比越高，有效位密度下降。NVFP4 在视觉编码器上的适用性取决于激活的块内一致性：卷积与线性层的通道间幅值差异大，需要逐通道或小块缩放；LayerNorm 后激活分布相对集中，块可以放大以降低元数据开销。</p>\n<p>系统代价：NVFP4 把权重显存压到 BF16 的四分之一，视觉编码器权重驻留与 HBM 读取带宽同步下降，这是 Blackwell 上容量规划的关键杠杆；但 4 位尾数的表示能力有限，视觉特征重建误差显著高于 FP8，必须靠 token 合并与跨模态注意力近似共同吸收。工具链把量化精度与合并阈值作为联合搜索维度，正是因为 NVFP4 的误差不能由单一环节消化。具体例子：把视觉编码器 MLP 权重压到 NVFP4 而注意力投影保留 FP8，是常见的混合策略——MLP 对特征重建的敏感度低于注意力打分，误差传导路径更短。</p>\n\n<h3 id=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-18\">十八 · tcgen05、TMEM 与 2-SM MMA：指令层的推理形态</h3>\n<p>Blackwell 的 tcgen05 指令族把矩阵乘的累加器从寄存器文件搬到 Tensor Memory（TMEM），形成“异步 MMA + TMEM 累加”的流水线。其结构可抽象为：</p>\n<div class=\"formula\">$$\\text{issue: }\\ \\mathrm{tcgen05.mma}\\ (A,B)\\rightarrow\\mathrm{TMEM};\\qquad \\text{consume: }\\ \\mathrm{tcgen05.ld}\\ (\\mathrm{TMEM})\\rightarrow\\mathrm{registers}$$</div>\n<p>逐项解释：MMA 指令异步发射，累加结果写入 TMEM 而不占用通用寄存器；随后用加载指令把 TMEM 中的累加块取回寄存器做 epilogue（偏置、激活、量化）。TMEM 的容量与带宽成为新的约束：多个 MMA 流水可共享 TMEM 分块，但 epilogue 的读取节奏必须与 MMA 发射节奏匹配，否则 TMEM 读写成为瓶颈。2-SM MMA 让两个 SM 协作完成一次更大规模的矩阵乘，把 $M$ 维或 $N$ 维切分到两个 SM 的 Tensor Core 上，减少单 SM 的寄存器压力并提高大矩阵的利用率；代价是跨 SM 的数据交换与同步开销，对小矩阵不划算。</p>\n<p>推理系统代价：tcgen05 的异步特性提高了 Tensor Core 占用率，但要求 kernel 以流水线方式组织——视觉编码器的注意力与 MLP 可借 2-SM MMA 提升大 batch 下的吞吐；跨模态注意力层在视觉 token 被压缩后矩阵规模变小，2-SM 协作的同步开销可能超过收益，此时单 SM MMA 更合适。TMEM 的占用还影响并发 kernel 数量：TMEM 分块被占满时新 MMA 无法发射，表现为延迟抖动。具体例子：在 GB200 NVL72 上做分离式预填/解码时，预填侧的视觉编码器适合 2-SM MMA 拉高吞吐，解码侧的跨模态注意力因序列短、批内 token 少，应退回单 SM 路径以避免同步开销拖累每 token 延迟。</p>\n\n<h3 id=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-19\">十九 · 精度、合并与显存的联合标定</h3>\n<p>三类压缩步骤在同一流水线上耦合，量化精度决定视觉特征重建误差，合并阈值决定序列长度，二者共同决定跨模态注意力与 KV cache 的显存占用。可把部署容量写成：</p>\n<div class=\"formula\">$$\\text{Mem}_{\\mathrm{vis}}=L_{\\mathrm{merge}}\\cdot d\\cdot b_{\\mathrm{vis}}+W_{\\mathrm{enc}}\\cdot b_{W},\\qquad \\text{Lat}_{\\mathrm{enc}}\\propto \\frac{L_{\\mathrm{patch}}\\cdot d^{2}}{T_{\\mathrm{TC}}(b_{W},b_{\\mathrm{vis}})}$$</div>\n<p>逐项解释：$L_{\\mathrm{merge}}$ 是合并后的视觉序列长度，$d$ 是特征维度，$b_{\\mathrm{vis}}$ 是视觉特征每元素字节数（由精度决定），$W_{\\mathrm{enc}}$ 是编码器权重元素数，$b_W$ 是权重字节数；延迟项中 $L_{\\mathrm{patch}}$ 是原始 patch 数，$T_{\\mathrm{TC}}$ 是给定权重与激活精度下 Tensor Core 的有效吞吐。第一项说明：降低 $b_{\\mathrm{vis}}$（FP8/NVFP4）与降低 $L_{\\mathrm{merge}}$（更激进的合并）都能压缩显存，但前者抬高特征重建误差、后者损失细粒度信息，二者不是可独立优化的维度。第二项说明：精度提升吞吐的路径是 $T_{\\mathrm{TC}}$ 变大，但若累加精度或 TMEM 占用限制了流水线，实际延迟收益会被削弱。</p>\n<p>工程判断：标定顺序应是先定累加精度与 MMA 形态（决定 $T_{\\mathrm{TC}}$ 的上界），再定权重精度（决定 $W_{\\mathrm{enc}}\\cdot b_W$ 的显存底），最后在给定误差预算下搜索合并阈值 $L_{\\mathrm{merge}}$。反过来先压合并阈值再调精度，会把量化误差误归因为合并损失，导致回退组合选择失准。线上按 SLO 切换组合时，回退路径必须在请求入口完成，因为解码中途切换会破坏 KV cache 与已合并序列的一致性——这是工具链把组合选择放在入口处的直接原因。具体例子：长视频请求按帧采样控制 $L_{\\mathrm{patch}}$，单独成批以避免 KV cache 随帧数线性膨胀；其视觉编码器可用 NVFP4 权重压显存，但跨模态注意力层保留 FP8 与 FP32 累加以守住对齐精度，形成按段分配的混合精度配置。</p>\n\n<h3 id=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-20\">二十 · 压缩算子挂载点的失效边界与容量代价</h3>\n<p>AngelSlim 把视觉 token 压缩挂在视觉编码器输出边界，这一位置选择决定了收益与风险的不对称性：压缩后序列长度 L̂ 直接进入跨模态注意力与 KV cache 的显存预算，成为部署容量的第一约束。以批内视觉 token 总量计，KV 显存可写成 <span class=\"formula\">$$M_{\\mathrm{KV}} \\approx b\\cdot \\hat{L}\\cdot d\\cdot s\\cdot \\varepsilon$$</span>，其中 b 为批大小、d 为头维展开后的每 token 元素数、s 为层数、ε 为每元素字节数（FP16/BF16 为 2、FP8 为 1、NVFP4 按块缩放另计元数据开销）。逐项看：b 由 SLO 延迟预算与解码侧算力决定，L̂ 由相似度阈值裁剪，ε 由量化档位选择。三者中只有 L̂ 与 ε 是压缩工具链可控的，但 b 会反向放大它们——阈值放松一档，长视频请求的 L̂ 增长会以批为单位吃掉显存余量，此时即使 ε 降到 FP8 也未必补得回来。失效条件因此很具体：当视觉序列长度随分辨率或帧数增长、而批内混入长视频请求时，压缩收益被批调度稀释，KV cache 随帧数线性膨胀，短请求批被拖累。工程上必须把长视频请求单独成批，并在请求入口按帧采样策略先截断序列，再谈量化档位。</p>\n<p>视觉编码器量化以权重与激活为对象，其误差不孤立存在，而与 token 合并强度耦合。合并按相似度阈值裁剪序列，阈值过松损失细粒度视觉信息，过紧则合并开销抵消压缩收益；量化精度下降会改变特征相似度分布，从而改变同一阈值下的实际裁剪比例。二者必须联合标定，单独调优任一项都会高估收益。可用的代理是压缩损失中的视觉重建项 <span class=\"formula\">$$\\lambda_{2}\\sum_{i}\\left\\|f_{v}(x_{i})-\\hat{f}_{v}(x_{i})\\right\\|_{2}^{2}$$</span>，它同时吸收量化误差与合并引入的特征偏移，但注意该项只约束编码器输出，不约束跨模态对齐层之后的分布漂移。系统代价上，视觉编码器是计算密集段，FP8 激活量化能提升 Tensor Core 利用率并压低编码段延迟，但若合并阈值同步放松，跨模态注意力与解码段的 KV 显存反而上升——收益归因必须按段记录，否则会把编码段的提速误记为端到端收益。</p>\n<p>跨模态注意力近似作用于对齐层，压缩前后接口一致使部署侧可按请求切换组合，但近似误差会传导到解码输出分布，这正是压缩损失第三项 KL 所度量的对象。该 KL 项对视觉侧误差敏感、对语言侧量化误差不敏感，因此不能作为统一验收指标：语言解码器的权重量化误差主要由第一项 L2 约束，两者需分别设阈。更硬的边界在回退路径——组合切换必须在请求入口完成，解码中途切换会破坏 KV cache 一致性，已分配的 L̂ 与已写入的 KV 块无法在生成过程中重排。这意味着线上按 SLO 超预算回退时，只能在下一个请求生效，当前请求要么带病跑完、要么被丢弃重排。容量规划应据此预留回退余量：保守组合的显存占用才是真正的容量下限，激进组合只是提升平均吞吐的手段。</p>\n<table class=\"mini\"><thead><tr><th>挂载点</th><th>可控变量</th><th>主要系统代价</th><th>失效条件</th></tr></thead><tbody><tr><td>视觉编码器量化</td><td>权重/激活精度档位</td><td>编码段延迟、特征重建误差</td><td>与合并阈值未联合标定</td></tr><tr><td>token 合并</td><td>相似度阈值</td><td>KV 显存、跨模态注意力负载</td><td>长视频混批、阈值过松</td></tr><tr><td>跨模态注意力近似</td><td>近似算子开关</td><td>输出分布漂移、KL 上升</td><td>解码中途切换破坏 KV 一致性</td></tr></tbody></table>\n<p>三类算子以插件形式独立启停，便于按硬件档位归因显存与延迟，但独立启停不等于独立验收：合并改变序列长度会改变量化校准数据的分布，注意力近似改变对齐层输入会改变 KL 的基准分布。工具链在离线阶段为每个档位选定的组合，本质是在这三条耦合链上取的折中点，材料未给出精度损失边界与失败模式的量化结论，因此任何档位的组合都必须以部署侧实测的延迟与显存代理指标回放确认，而非以离线损失值直接外推。</p>\n<h3 id=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-21\">二十一 · 显存账本的四个账户：权重、激活、KV、临时缓冲</h3>\n<p>在 Blackwell 上做多模态推理的容量规划，第一步不是选量化格式，而是把显存拆成四个互不挪用的账户。权重账户是静态的：视觉编码器与语言解码器各自持有参数，AngelSlim 允许两者分别设定精度，因此同一份工具链配置下可能出现编码器 FP8、解码器 NVFP4 的混合账本。激活账户是瞬态的，峰值由视觉编码器前向的 patch 序列长度与解码侧批内最大 token 数共同决定。KV cache 账户是随请求增长的，其规模由压缩后的视觉序列长度加上文本序列长度乘以层数与头维度决定。第四账户是临时缓冲：tcgen05 的 TMEM 分配、跨模态注意力对齐层的中间张量、以及 token 合并时的相似度矩阵，都属于不可忽略但常被漏算的部分。</p>\n<p>账本的关键约束是 KV 账户与激活账户共享同一块 HBM3e 容量，而权重账户在服务启动后基本固定。设视觉 token 压缩比为 $r_v$（压缩后长度除以原始 patch 数），批大小为 $B$，解码层数为 $L$，KV 头数为 $H$，头维度为 $d$，每元素字节数为 $b_{kv}$，则单批 KV 显存为：</p>\n<div class=\"formula\">$$M_{\\mathrm{KV}} = B \\cdot L \\cdot H \\cdot d \\cdot b_{kv} \\cdot 2 \\cdot \\left(r_v N_v + N_t\\right)$$</div>\n<p>其中 $N_v$ 为原始视觉 patch 数，$N_t$ 为文本 token 数，系数 2 对应 K 与 V 两份。这个式子说明一件事：$r_v$ 的每一次下调都在线性削减 KV 账户，而 $N_v$ 随分辨率平方增长，因此高分辨率请求的容量压力主要落在视觉侧而非文本侧。工程上把 $r_v$ 作为部署档位的第一旋钮，正是因为它在账本里的杠杆最长。</p>\n<p>具体例子：一个视频请求按帧采样后产生数千级 patch，若不做合并，KV 账户会被视觉序列主导，短请求批被迫缩小；把合并阈值调紧使 $r_v$ 下降后，同一批可容纳更多并发，但细粒度视觉信息随之损失——这正是 AngelSlim 要求阈值与量化精度联合标定的原因。</p>\n\n<h3 id=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-22\">二十二 · 分页与块分配：压缩后长度如何改写分页粒度</h3>\n<p>连续批处理依赖分页 KV cache 把逻辑序列映射到物理块，块大小通常按固定 token 数切分。视觉 token 压缩改变了这个映射的前提：压缩后的视觉序列长度不再是 patch 数的整数倍关系，且不同请求的 $r_v$ 可能因内容相似度分布而异。若仍按统一块大小分配，短视觉序列会产生内部碎片，长视频序列则跨块频繁。AngelSlim 的插件式挂载允许在视觉编码器输出边界完成合并，因此分页器看到的已经是压缩后长度，块分配可按该长度做首次适配，减少跨块指针跳转。</p>\n<p>代价体现在两个方向。碎片方向：块大小选大则短请求浪费尾部空间，选小则块表膨胀、页表遍历开销上升。带宽方向：跨块注意力读取的物理地址不连续，HBM3e 的突发传输效率下降，跨模态注意力层在压缩后视觉 token 与文本 token 间对齐时，若视觉块与文本块不在同一内存分区，读取延迟会叠加。工程判断是让视觉块与文本块尽量落在同一 HBM 栈的相邻分区，把跨模态对齐的地址局部性做出来。</p>\n<p>伪代码思路：请求入口先按 $r_v$ 估计压缩后长度 $\\hat{N}_v = r_v N_v$，以 $\\hat{N}_v + N_t$ 为逻辑长度向分页器申请块数 $\\lceil (\\hat{N}_v + N_t)/P \\rceil$，$P$ 为块大小；解码中途不重新分页，因为组合切换会破坏 KV 一致性，回退必须在入口完成。这条规则直接来自 AngelSlim 的回退路径约束：解码中途切换组合会使已分配的块与新的压缩比不匹配，KV 内容失效。</p>\n\n<h3 id=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-23\">二十三 · 压缩与复用：合并阈值、量化精度与跨层共享</h3>\n<p>视觉 token 合并按相似度阈值裁剪序列，阈值过松损失细粒度信息，过紧则合并开销抵消收益。合并本身要算相似度矩阵，其显存与计算随 $N_v^2$ 增长，因此合并模块的临时缓冲在长视频请求上可能成为激活账户的峰值来源。把合并放在视觉编码器输出边界而非更早，是为了让编码器前向仍按原始 patch 数执行、保持接口一致，代价是编码器激活峰值不随 $r_v$ 下降——这是账本里一个容易被误判的点：压缩收益落在 KV 与跨模态注意力，不落在视觉编码器本身。</p>\n<p>复用维度有三层。层内复用：跨模态注意力近似作用于对齐层，压缩前后接口一致使同一份视觉特征可被多个解码步复用，避免每步重算视觉侧。跨请求复用：相同图像或视频前缀的请求可共享视觉 KV 块，按内容哈希索引，命中时跳过视觉编码器前向与合并。跨档位复用：AngelSlim 在离线阶段为每个硬件档位选定量化与合并组合，B200、B300、GB200 NVL72 各自持有候选组合表，线上按 SLO 切换，复用的是组合决策而非张量本身。</p>\n<p>量化的账本效应是双向的：权重精度下降释放权重账户，但激活量化若在视觉编码器上过激，视觉特征重建误差上升，合并阈值的有效范围被压缩，反而需要更保守的 $r_v$ 来保精度，KV 账户收益缩水。损失函数里 $\\lambda_2$ 项正是这一耦合的显式表达，联合标定的意义在于让两个旋钮不互相拆台。</p>\n\n<h3 id=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-24\">二十四 · 卸载：把哪一部分挪出 HBM，代价记在谁头上</h3>\n<p>卸载在多模态推理里有三个候选对象：视觉编码器权重、冷请求的 KV 块、以及合并模块的临时缓冲。视觉编码器权重卸载到主机内存的收益是释放权重账户，代价是每次前向的 PCIe 传输延迟，且视觉编码器前向是每请求一次而非每 token 一次，因此摊薄后延迟可接受——前提是批内请求的视觉编码器调用被聚合成一次，否则传输次数随请求数线性增长。KV 块卸载适用于长视频请求：把已完成帧对应的 KV 块换出，保留当前窗口，代价是换入时的带宽突发，与解码步的 HBM 读取竞争。</p>\n<p>临时缓冲卸载基本不可行：合并相似度矩阵在计算中被立即消费，换出再换入的往返延迟超过其驻留收益。工程判断是把合并模块的块大小调小、分块计算相似度，用计算换显存，而不是用带宽换显存。</p>\n<p>卸载的账本必须与 SLO 绑定：卸载决策在请求入口完成，与压缩组合切换同一时机。若某请求被判定为长视频，入口处即选择“KV 块可换出 + 保守合并阈值”的组合，避免解码中途因显存不足触发换出而破坏延迟预算。功耗侧，卸载降低 HBM 驻留但增加互连活动，GB200 NVL72 机架内 NVLink 5 的带宽足以承载权重换入，但跨节点卸载会把压力推到 fabric 上，容量规划时需把卸载流量计入互连预算。</p>\n\n<h3 id=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-25\">二十五 · 带宽瓶颈定位：HBM3e 容量与带宽的除法</h3>\n<p>HBM3e 的容量账本按栈计算：单栈容量与栈数相乘得到单 GPU 容量，再乘以节点内 GPU 数得到节点容量。容量决定能放多少 KV 块，带宽决定每步解码能读多少。解码步的带宽需求近似为：每步读取全部权重一次（受批大小摊薄）加上读取该步涉及的 KV 块。设权重字节数为 $W_b$，KV 每 token 字节数为 $k_b$，批内总 token 数为 $T$，则每步 HBM 读取量约为 $W_b + k_b T$，解码延迟下界由该读取量除以有效带宽给出。</p>\n<div class=\"formula\">$$t_{\\mathrm{step}} \\gtrsim \\frac{W_b + k_b\\,T}{\\mathrm{BW}_{\\mathrm{eff}}}$$</div>\n<p>这个式子给出瓶颈判据：当 $k_b T \\ll W_b$ 时是权重带宽瓶颈，增大批大小可摊薄权重读取、提升吞吐；当 $k_b T$ 与 $W_b$ 同量级时进入 KV 带宽瓶颈，此时增大批大小不再线性提升吞吐，反而拉长每步延迟。视觉 token 压缩的作用正是压低 $k_b$ 中视觉部分，把拐点右移，让更大的批仍处在权重瓶颈区。</p>\n<p>具体例子：一个以图像为主的请求批，压缩前视觉 KV 占每 token 字节数的主要部分，批稍大即进入 KV 瓶颈；压缩后视觉部分下降，同样批大小下每步读取量回落，解码延迟下界改善。但若合并阈值过紧导致精度损失，回退保守组合又会使 $k_b$ 回升——带宽收益与精度收益在同一根旋钮上反向，这正是 AngelSlim 把监控指标与回退路径做进工具链的工程理由。</p>\n\n<h3 id=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-26\">二十六 · 可复算的显存预算：从档位到并发数</h3>\n<p>给出一个可复算的流程，读者可代入自己的模型参数。第一步，确定权重账户：编码器参数量乘其精度字节数，解码器参数量乘其精度字节数，两者相加并预留激活峰值系数。第二步，按第二节公式算单请求 KV 字节数，代入 $r_v$、$N_v$、$N_t$、$L$、$H$、$d$、$b_{kv}$。第三步，确定块大小 $P$ 与块表开销，按 $\\lceil (\\hat{N}_v + N_t)/P \\rceil$ 算块数，块表每项指针字节数乘以块数计入临时账户。第四步，用容量减去权重、激活峰值、临时缓冲，余量除以单请求 KV 字节数得到理论并发上限。第五步，用第五节的带宽式子校验该并发下是否已进入 KV 瓶颈，若是则下调并发或调紧 $r_v$。</p>\n<table class=\"mini\"><thead><tr><th>账户</th><th>决定因素</th><th>随什么增长</th><th>可调旋钮</th></tr></thead><tbody><tr><td>权重</td><td>参数量 × 精度字节</td><td>模型规模</td><td>编码器/解码器分别量化</td></tr><tr><td>激活峰值</td><td>patch 序列长度 × 批内最大 token</td><td>分辨率、帧数</td><td>帧采样、批聚合</td></tr><tr><td>KV</td><td>$r_v N_v + N_t$ × 层数 × 头数 × 头维度</td><td>压缩后长度、批大小</td><td>合并阈值、块大小</td></tr><tr><td>临时缓冲</td><td>相似度矩阵、TMEM、块表</td><td>$N_v^2$、块数</td><td>分块计算、块大小</td></tr></tbody></table>\n<p>这张表的用法是把每个账户的旋钮与它影响的另一账户显式连起来：合并阈值下调同时降低 KV 与临时缓冲，但抬高视觉特征重建误差；块大小下调降低碎片但抬高块表开销；编码器量化降低权重但可能压缩合并阈值的有效范围。AngelSlim 的离线档位选择本质上是在这张表上做多目标搜索，线上回退则是在实测偏离预算时退回保守格点。容量规划的最终判断落在一条：先确认当前批处在权重瓶颈还是 KV 瓶颈，再决定把预算花在增大并发还是调紧压缩——两个方向对延迟与精度的边际代价完全不同，混着调会把归因做丢。</p>\n\n<h3 id=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-27\">二十七 · 压缩组合的失效边界与显存账本复算</h3>\n<p>视觉 token 合并的收益并非单调：设原始视觉序列长度为 <span class=\"formula\">$$L_v$$</span>、合并后为 <span class=\"formula\">$$\\hat{L}_v$$</span>，则跨模态注意力与解码侧 KV cache 的显存占用近似正比于 <span class=\"formula\">$$\\hat{L}_v + L_t$$</span>（<span class=\"formula\">$$L_t$$</span> 为文本 token 数）。合并阈值过松时 <span class=\"formula\">$$\\hat{L}_v$$</span> 下降有限，合并算子自身的相似度计算与重排开销却已计入视觉编码器后的关键路径；阈值过紧则细粒度视觉信息丢失，跨模态注意力近似误差经对齐层传导到解码输出分布，表现为长尾 token 概率偏移。工具链把合并挂在编码器输出边界，意味着这一开销无法被后续批调度摊薄——它是每请求的固定延迟项，短请求批中占比尤其突出。</p>\n<p>可复算的显存预算应按段拆账，而非只报一个总占用。以单请求为例：视觉编码器激活约占 <span class=\"formula\">$$B_v \\cdot L_v \\cdot d_v \\cdot s$$</span>（<span class=\"formula\">$$s$$</span> 为激活字节数，随量化精度档位变化），压缩后视觉 token 的 KV 占 <span class=\"formula\">$$2 \\cdot \\hat{L}_v \\cdot d \\cdot s_{kv} \\cdot n_{layer}$$</span>，文本 KV 同理按 <span class=\"formula\">$$L_t$$</span> 计。三项中只有第一项随批内并发线性增长且受编码器精度档位支配，后两项随批内总 token 数增长。工程判断是：当 <span class=\"formula\">$$\\hat{L}_v$$</span> 已被压到与 <span class=\"formula\">$$L_t$$</span> 同量级时，继续加严合并阈值的边际显存收益迅速衰减，而重建误差项 <span class=\"formula\">$$\\lambda_2$$</span> 主导的损失开始抬升，此时应转向视觉编码器量化档位而非 token 合并。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>系统代价</th><th>可观测信号</th></tr></thead><tbody><tr><td>合并阈值过紧</td><td>视觉特征重建误差上升，解码分布偏移</td><td>输出 KL 代理指标抬升</td></tr><tr><td>量化与合并单独调优</td><td>显存收益被高估，延迟归因失真</td><td>分段显存账本与总占用不符</td></tr><tr><td>解码中途切换组合</td><td>KV cache 与压缩后序列长度不一致</td><td>请求内 token 位置错位</td></tr><tr><td>长视频与短请求同批</td><td>KV cache 随帧数线性膨胀，拖累整批</td><td>批内尾延迟抬升</td></tr></tbody></table>\n<p>回退路径的代价必须前置到请求入口：组合切换若发生在解码中途，已分配的 KV cache 块按旧 <span class=\"formula\">$$\\hat{L}_v$$</span> 布局，与新组合的序列长度不匹配，只能整请求重算，等价于一次预填重放。因此工具链的保守组合回退应在预处理段完成判定，用离线阶段记录的每档位显存与延迟代理指标做查表，而不是在解码循环里动态试探。视频输入另有一条独立边界：帧采样策略决定 <span class=\"formula\">$$L_v$$</span> 的上界，长视频请求单独成批是避免 KV cache 线性膨胀拖累短请求批的唯一低成本手段，其代价是批利用率下降，需在容量规划中按视频请求占比预留显存块。</p>\n<h3 id=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-28\">二十八 · 连续批处理在视觉序列长度不均时的调度代价</h3>\n<p>AngelSlim 的工具链把视觉 token 压缩挂在视觉编码器输出边界，压缩后的序列长度直接决定跨模态注意力与 KV cache 的显存占用。这意味着批调度器面对的请求不再是等长的文本序列，而是长度随分辨率、帧数、合并阈值三者共同波动的视觉序列。连续批处理（continuous batching）在解码阶段按 token 步推进、请求完成即出批、新请求即入批，其收益来自把等待时间填进空闲的 SM 与显存带宽；但在多模态场景下，这个收益会被视觉序列的长度方差吃掉一部分。</p>\n<p>设批内请求集合为 $B$，第 $i$ 个请求的视觉序列长度为 $L^{v}_{i}$、文本序列长度为 $L^{t}_{i}$，则单步解码的注意力计算量近似正比于 $\\sum_{i\\in B}(L^{v}_{i}+L^{t}_{i})$，而 KV cache 占用正比于同一求和乘以层数与头维度。调度器的核心判断是：入批一个新请求所增加的显存块，是否还能被当前批的空闲算力吸收。当 $L^{v}_{i}$ 远大于批内均值时，这个请求会单方面抬高整批的每步延迟，尾延迟随之恶化。工程上的做法是给视觉序列长度设分档阈值，把长视频请求与短图像请求分到不同批队列，而不是让调度器按到达顺序混排。</p>\n<p>代价体现在两个方向：批越大，每步解码的显存带宽压力越高，因为 KV cache 读取量随批内总序列长度线性增长；批越小，SM 占用率下降，视觉编码器与解码器之间的流水空隙变大。Blackwell 的 B200/B300 单卡显存带宽足以支撑较大的批，但 GB200 NVL72 机柜级部署里，跨节点请求的视觉特征传输会引入额外延迟，调度器必须把“批内长度方差”和“跨节点传输”一起纳入入批决策。一个具体例子：同一批里混入一个高帧率视频请求，其压缩后视觉序列仍是短图像请求的数倍，解码每步都要为它多读一份 KV cache，短请求的 token 间隔被拉长，SLO 尾延迟指标先于平均吞吐报警。</p>\n\n<h3 id=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-29\">二十九 · chunked prefill 与视觉编码器前向的切分边界</h3>\n<p>chunked prefill 把长预填拆成若干块，与解码步交错执行，目的是避免一个长预填独占整个批次、把已在解码的请求饿死。AngelSlim 的结构里，预填阶段包含视觉编码器前向、token 合并、跨模态注意力对齐三段，切分点不能随意选：视觉编码器输出的是逐 patch 特征序列，token 合并按相似度阈值裁剪，跨模态注意力在压缩后的视觉 token 与文本 token 间对齐。若把切分点放在视觉编码器内部，合并模块看到的序列是不完整的，相似度阈值失去全局参照；若放在合并之后、对齐之前，则每块预填都要重复一次对齐层的部分状态写入。</p>\n<p>可行的切分策略是以“压缩后视觉 token 块”为单位：视觉编码器整段前向完成后得到完整特征序列，合并模块一次性裁剪，随后把压缩后的视觉 token 按固定块大小送入跨模态注意力与语言解码的预填。这样每块的 KV cache 写入是连续的，块间不重复计算。伪代码思路是：对请求 $r$，先算 $n_{v}=\\text{merge}(f_{v}(x))$，再按块大小 $c$ 切成 $\\lceil n_{v}/c\\rceil$ 块，调度器每步取一块与当前解码批拼接，块内做因果注意力，块间靠已写入的 KV cache 衔接。</p>\n<p>代价是显存峰值：视觉编码器整段前向要求一次性容纳未压缩的视觉特征，其显存占用正比于原始 patch 数而非压缩后长度。分辨率越高、帧数越多，这段峰值越突出，可能超过解码阶段的稳态占用。工程判断是：对长视频请求，先做帧采样把原始 patch 数压到编码器显存预算内，再走整段前向与合并；对短图像请求，块大小可以取大一些以减少调度开销。chunked prefill 的收益在尾延迟上最明显——它把长预填的延迟摊到多个解码步，短请求的 token 间隔不再被单个长预填阻塞，但代价是长预填请求自身的完成时间被拉长，调度器需要在两者间按 SLO 分层设置块大小。</p>\n\n<h3 id=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-30\">三十 · 优先级、抢占与压缩组合的回退路径</h3>\n<p>AngelSlim 的压缩组合按 SLO 延迟预算选择，线上超预算时回退保守组合，且回退路径需在请求入口完成以避免解码中途切换。这条约束直接决定了抢占的粒度：抢占不能发生在解码中途，因为压缩组合一变，KV cache 的序列长度与布局都变，中途切换会破坏缓存一致性。可行的抢占单位是“请求级”——调度器在请求入口按当前 SLO 与硬件档位选定组合，运行中若监控到该组合超出延迟预算，只对新到达请求切换组合，已在解码的请求继续用原组合跑完。</p>\n<p>优先级设计上，视觉序列长度是天然的分层依据：短图像请求延迟敏感、易满足 SLO，长视频请求吞吐敏感、单请求占用大。把长视频请求放在低优先级队列、单独成批，可以避免它拖累短请求批的尾延迟；当高优先级队列空时，调度器再把长视频请求填入空闲算力。抢占的代价是重算：被抢占的请求若已写入部分 KV cache，恢复时要重新对齐视觉 token 与文本 token 的位置编码，跨模态注意力近似算子也要按新组合重算对齐层，这部分重算量正比于已处理的视觉 token 数。</p>\n<p>一个具体机制是回退触发的判定：监控采集每请求延迟与显存占用，当某组合的滑动窗口延迟超过预算，入口处把该组合标记为降级，后续请求改用保守组合（更低的量化精度档位或更强的 token 合并）。代价是保守组合的视觉特征重建误差更大，输出分布 KL 上升，精度收益让位于延迟达标。工程上要把“组合切换”与“请求优先级”解耦：切换是入口策略，抢占是批内策略，两者混在一起会让归因失效——分不清尾延迟恶化是组合选错还是批内长度方差所致。</p>\n\n<h3 id=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-31\">三十一 · 分离式预填/解码与视觉编码器的放置</h3>\n<p>分离式预填/解码（disaggregated prefill/decode）把预填与解码拆到不同实例，预填侧算力密集、解码侧显存带宽密集，各自按需扩缩。AngelSlim 的训练配方写明并行拓扑按视觉编码器与语言解码分离部署、跨模态注意力层随解码侧放置。这带来一个放置问题：视觉编码器前向与 token 合并属于预填侧的重计算，跨模态注意力对齐却要读解码侧的 KV cache，若对齐层整体放在解码侧，预填侧就要把压缩后的视觉 token 传给解码侧，传输量正比于压缩后序列长度而非原始 patch 数——这正是 token 合并的收益所在。</p>\n<p>传输代价要按 NVLink 5 与跨节点两条路径分别估算：机内预填到解码走 NVLink，带宽足以支撑压缩后视觉 token 的搬运；GB200 NVL72 机柜内跨节点走 NIXL 之类的传输层，延迟随跳数上升。若把视觉编码器也放在解码侧，预填侧只剩文本预填，视觉计算与解码争抢同一批 SM，分离的收益被抵消。因此放置判断是：视觉编码器与合并模块放预填侧，对齐层与语言解码放解码侧，压缩后视觉 token 作为两者之间的传输载荷。</p>\n<p>代价体现在预填侧的显存峰值与解码侧的 KV cache 稳态占用分离后，两侧可以独立按档位配置量化精度：视觉编码器量化在预填侧标定，解码器量化在解码侧标定，互不牵制。一个例子：长视频请求在预填侧做帧采样与合并，压缩后视觉 token 经 NVLink 送到解码侧，解码侧按压缩后长度分配 KV cache 块；若预填侧排队过长，调度器可以把该请求的预填块拆得更细，与解码侧的批交错推进，代价是预填侧显存峰值随块数上升。</p>\n\n<h3 id=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-32\">三十二 · 尾延迟的压法：长度分档、块大小与组合切换的联合标定</h3>\n<p>尾延迟（p99 token 间隔）在多模态推理里主要由三件事驱动：批内视觉序列长度方差、长预填的独占时长、压缩组合切换的抖动。压尾延迟不是单点调参，而是三者的联合标定。长度分档决定批内方差上限；块大小决定长预填被摊薄的程度；组合切换的入口判定决定抖动是否传导到解码步。</p>\n<p>设批内视觉序列长度的分档阈值为 $\\tau$，块大小为 $c$，组合切换的延迟预算为 $D_{\\mathrm{slo}}$，则调度器的联合约束可写成：批内所有请求满足 $L^{v}_{i}\\le\\tau$，单块预填的预计时长不超过解码步间隔的若干倍，且入口处所选组合的代理延迟不超过 $D_{\\mathrm{slo}}$。这三个约束互相牵制：$\\tau$ 放大会提高批利用率但抬高方差，$c$ 变小会降低预填独占但增加调度开销，组合越激进则 $D_{\\mathrm{slo}}$ 越紧、回退越频繁。</p>\n<p>工程上的压法是把尾延迟指标挂到请求入口而非批内：入口按请求的视觉序列长度预估其所属分档，选组合、定块大小，批内只做入批与出批，不做组合变更。这样尾延迟的归因清晰——若 p99 恶化，先看分档阈值是否让长请求混入短批，再看块大小是否让预填独占解码步，最后看组合是否在入口被误选。代价是入口预估本身有误差：帧采样策略与合并阈值在入口处只能按请求元数据估算，实际压缩后长度要到视觉编码器前向与合并完成后才确定，预估偏差会让分档失准。缓解办法是把合并阈值的标定结果与帧采样策略一起写进入口配置，使预估基于已标定的压缩比而非猜测。</p>\n<table class=\"mini\"><thead><tr><th>调度手段</th><th>主要收益</th><th>主要代价</th><th>适用请求形态</th></tr></thead><tbody><tr><td>连续批处理 + 长度分档</td><td>提高 SM 占用，压低短请求尾延迟</td><td>长请求单独成批时批利用率下降</td><td>短图像请求为主</td></tr><tr><td>chunked prefill 按压缩后 token 块切分</td><td>长预填不独占解码步</td><td>视觉编码器整段前向的显存峰值</td><td>长视频、高分辨率图像</td></tr><tr><td>入口级组合切换与回退</td><td>延迟超预算时保 SLO</td><td>保守组合精度收益下降</td><td>混合负载、SLO 分层</td></tr><tr><td>分离式预填/解码 + 视觉编码器放预填侧</td><td>两侧独立扩缩与独立量化标定</td><td>压缩后视觉 token 的跨节点传输延迟</td><td>机柜级部署、长视频</td></tr></tbody></table>\n<p>最后落在具体机制上：AngelSlim 的插件式挂载使量化、合并与注意力近似可独立启停，调度器因此可以把“压缩组合”当作一个可切换的调度维度，而不是固定配置。判断一个部署档位是否选对，看的是入口预估的压缩后长度与实际合并后长度的偏差是否落在分档阈值内；偏差大则分档失准、尾延迟归因失效，此时应先联合标定合并阈值与量化精度，再调块大小与批策略，而不是反过来用批调度去掩盖压缩参数的不确定性。</p>\n<h3 id=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-33\">三十三 · 切分维度：从视觉序列到解码层的并行拓扑</h3>\n<p>AngelSlim 的并行问题不是“把模型切开”这么简单，而是压缩后的张量形状决定切分是否划算。工具链五段中，视觉编码器输出边界是 token 压缩挂载点，压缩后视觉序列长度直接决定跨模态注意力与 KV cache 的显存占用，因此并行拓扑必须按压缩后的形状来排。工程上的默认排法是：视觉编码器与语言解码分离部署，跨模态注意力层随解码侧放置，这样视觉编码器的 TP 切分不受解码侧 TP 组约束，两侧可以选不同并行度。</p>\n<p>四种切分的代价结构不同。TP 切分权重与激活，每层前向都要在组内做 All-Reduce，通信量与隐藏维和批大小成正比；EP 切分 MoE 专家，路由后产生 All-to-All，通信量随被激活专家数与 token 数增长；PP 切分层，只在阶段边界传激活，通信量小但引入流水气泡；DP 复制权重，只在梯度或参数同步时需要通信，推理路径上几乎无通信。对多模态请求，视觉 token 压缩后序列变短，跨模态注意力的 TP All-Reduce 通信量随之下降，但视觉编码器本身的 TP 组若按未压缩序列长度配置，就会出现“切得比实际需要更细”的浪费。</p>\n<p>一个具体例子：GB200 NVL72 单机架内 72 个 GPU 通过 NVLink 5 与 NVSwitch 全互联，TP 组可以跨 8 卡甚至更大范围而不经过 InfiniBand。把跨模态注意力层放在解码侧、用 TP=8 切分，All-Reduce 走 NVLink 域内；视觉编码器单独用 TP=4 并配 DP=2 复制，两侧通过 NIXL 在节点内传视觉特征张量。这样视觉编码器的并行度按压缩前 patch 数配置，解码侧按压缩后序列长度配置，避免用同一套并行度硬套两段负载。</p>\n<div class=\"formula\">$$T_{\\text{step}} \\approx \\max\\left(T_{\\text{comp}},\\ \\frac{C_{\\text{comm}}}{B_{\\text{link}}}\\right) + T_{\\text{attn}}(L_{\\text{vis}}^{\\text{comp}},\\,L_{\\text{txt}})$$</div>\n<p>式中 $C_{\\text{comm}}$ 为该步通信字节数，$B_{\\text{link}}$ 为链路有效带宽，$L_{\\text{vis}}^{\\text{comp}}$ 为压缩后视觉序列长度。这个式子说明：压缩把 $L_{\\text{vis}}^{\\text{comp}}$ 压小，注意力计算项下降；但如果并行度没跟着调，通信项不变，瓶颈就从计算转到通信。</p>\n\n<h3 id=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-34\">三十四 · NVLink 5 与 NVSwitch：域内通信的带宽账</h3>\n<p>Blackwell 世代的 NVLink 5 把单 GPU 对外链路带宽抬到每方向百 GB/s 量级，NVL72 机架用 NVSwitch 做全互联，任意两卡之间一跳可达。这对 TP 与 EP 的意义不同：TP 的 All-Reduce 是组内规约，延迟敏感、消息小、频次高，走 NVSwitch 域内可以把每层同步开销压到可接受范围；EP 的 All-to-All 是路由分发，消息大小不均、存在热点专家，NVSwitch 的全互联能缓解热点，但无法消除路由不均衡本身。</p>\n<p>推理系统代价要按“每 token 每层”算。以 TP=8 切分一个隐藏维为 $H$ 的解码层，每层前向两次 All-Reduce（注意力输出与 MLP 输出），每次传输约 $2 \\times B \\times H \\times \\text{sizeof(dtype)}$ 字节，$B$ 为批内 token 数。若用 FP8 权重与激活，字节数减半，通信项同步减半——这是量化对并行拓扑的间接收益，也是 AngelSlim 把量化与切分放在同一工具链里联合标定的原因。视觉编码器量化以权重与激活为对象，精度选择与 token 合并强度共同决定视觉特征重建误差，量化精度一变，TP 组的通信预算也要重算。</p>\n<p>具体机制上，NIXL 负责跨节点、跨进程的张量传输，把视觉编码器产出的特征从编码器实例搬到解码侧跨模态注意力层。它不走集合通信语义，而是点对点搬运，适合分离式部署中“编码器在一组卡、解码器在另一组卡”的形态。代价是它不参与 TP 组内规约，因此不能替代 All-Reduce；工程判断是：域内规约用 NCCL 走 NVLink，跨段特征搬运用 NIXL，两者边界要划在跨模态注意力层之前。</p>\n<table class=\"mini\"><thead><tr><th>通信原语</th><th>典型位置</th><th>消息特征</th><th>主要代价</th></tr></thead><tbody><tr><td>All-Reduce</td><td>TP 组内每层</td><td>小消息、高频</td><td>延迟敏感，受组大小与 dtype 影响</td></tr><tr><td>All-to-All</td><td>EP 路由后</td><td>大小不均、有热点</td><td>路由不均衡放大尾延迟</td></tr><tr><td>点对点（NIXL）</td><td>编码器→解码器</td><td>大张量、低频</td><td>带宽受限，需与计算重叠</td></tr><tr><td>PP 边界传激活</td><td>阶段之间</td><td>中等、按微批</td><td>流水气泡</td></tr></tbody></table>\n\n<h3 id=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-35\">三十五 · 通信何时成为瓶颈：三个可判定的条件</h3>\n<p>第一个条件是压缩比超过并行度调整速度。视觉 token 合并按相似度阈值裁剪序列，阈值调紧后 $L_{\\text{vis}}^{\\text{comp}}$ 骤降，注意力计算时间缩短，但 TP 组大小没变，All-Reduce 时间不变，于是通信占比上升。判据是 $C_{\\text{comm}}/B_{\\text{link}} &gt; T_{\\text{comp}}$，一旦成立，继续压缩视觉 token 不再降延迟，反而把预算浪费在同步上。</p>\n<p>第二个条件是批内序列长度离散。长视频请求按帧采样控制序列长度，若与短请求混批，KV cache 按最长序列分配，批内多数 token 处于“陪跑”状态，TP All-Reduce 却按整批 token 数计费。工程做法是长视频请求单独成批，避免 KV cache 随帧数线性膨胀拖累短请求批；代价是批利用率下降，吞吐让位于尾延迟。</p>\n<p>第三个条件是 EP 路由不均衡。MoE 层在 EP 切分下，热门专家收到的 token 数远超均值，All-to-All 的尾延迟由最热专家决定。判据是最大专家负载与均值之比，比值越高，NVSwitch 全互联的收益越被路由不均衡吃掉。此时应调路由温度或加专家容量因子，而不是加卡。</p>\n<p>一个具体例子：某多模态服务在 B200 上用 TP=8 跑解码，视觉编码器 TP=4，跨模态注意力随解码侧。上线后发现压缩组合切到激进档时端到端延迟不降反升，按上述判据定位到 All-Reduce 占比越过计算项，于是把解码侧 TP 从 8 降到 4、把省下的卡转给 DP 复制解码器，通信项减半而计算项仅微增，延迟回到预算内。这个调整不需要改模型，只需要在工具链的部署档位里换并行配置。</p>\n\n<h3 id=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-36\">三十六 · 压缩组合与并行配置的联合标定</h3>\n<p>AngelSlim 的插件式挂载让量化、合并与注意力近似可独立启停，但并行配置不是独立变量。压缩组合按 SLO 延迟预算选择，线上超预算时回退保守组合，回退路径需在请求入口完成以避免解码中途切换——这条约束直接限制了并行配置能否在线调整。解码中途换 TP 组会破坏 KV cache 的分片布局，因此并行度必须在请求入口随压缩组合一起锁定。</p>\n<p>离线阶段的做法是：对每个硬件档位（B200、B300、GB200 NVL72）枚举压缩组合与并行配置的笛卡尔积，用校准数据驱动量化与合并参数搜索，损失由权重量化误差、视觉特征重建误差与输出分布 KL 三项加权，同时记录每步的显存与延迟代理指标。代理指标里必须包含通信项，否则会选出“压缩很激进、并行度没跟上”的组合，线上回放时才发现延迟不达标。</p>\n<div class=\"formula\">$$\\mathcal{L}_{\\mathrm{comp}}=\\lambda_{1}\\|W-\\hat{W}\\|_{2}^{2}+\\lambda_{2}\\sum_{i}\\left\\|f_{v}(x_{i})-\\hat{f}_{v}(x_{i})\\right\\|_{2}^{2}+\\lambda_{3}\\,\\mathrm{KL}\\left(p_{\\theta}(y\\mid v,t)\\,\\|\\,p_{\\hat{\\theta}}(y\\mid \\hat{v},t)\\right)$$</div>\n<p>这个损失不含通信项，但 $\\lambda_{2}$ 的重建误差与 token 合并强度耦合：合并越狠，$\\hat{f}_{v}$ 偏离 $f_{v}$ 越多，$\\lambda_{2}$ 项越大，工具链会倾向选更保守的合并阈值。工程判断是把通信代理指标作为约束而非损失项——先按 SLO 过滤掉通信超预算的组合，再在剩余组合里最小化 $\\mathcal{L}_{\\mathrm{comp}}$。这样量化精度、合并阈值与并行度三者一起被约束在可部署集合内。</p>\n\n<h3 id=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-37\">三十七 · 失败模式与监控落点</h3>\n<p>材料未给出失败模式的量化结论，但可判定的工程风险有三类。其一是压缩组合切换在解码中途发生，KV cache 分片与新的 TP 组不匹配，直接破坏一致性；监控落点是请求入口的组合标记，一旦发现同一请求内组合变更即告警。其二是视觉 token 合并阈值与量化精度单独调优，合并阈值放松后视觉特征重建误差上升，量化误差被掩盖，线上表现为跨模态注意力近似误差传导到解码输出分布，精度损失归因不到具体步骤；监控落点是分段采集视觉特征重建误差与输出 KL。其三是长视频请求与短请求混批，KV cache 按最长序列分配，显存占用被少数请求拉高，TP 通信按整批计费，吞吐与尾延迟同时恶化；监控落点是批内序列长度方差与 KV cache 实际分配量。</p>\n<p>并行与通信的监控指标应成对采集：每层 All-Reduce 耗时与同层计算耗时之比、All-to-All 最大专家负载与均值之比、NIXL 搬运字节数与重叠窗口命中率。比值越过阈值即触发并行配置回退，回退动作与压缩组合回退共用请求入口的同一条路径。这样工具链的“可归因”才落到通信维度：显存收益来自 token 合并，延迟收益来自量化与并行度联合调整，两者不混在一起。</p>\n\n<h3 id=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-38\">三十八 · 压缩组合与并行拓扑的耦合边界</h3>\n<p>AngelSlim 的插件式压缩算子并不改变并行切分的语义，但它改变了每个切分维度上的张量形状与通信量。视觉 token 合并挂在视觉编码器输出边界，压缩后序列长度直接决定跨模态注意力层与 KV cache 的显存占用，因而决定了 TP 组内每卡需要承载的激活分片与 EP 组间 All-to-All 的负载。工程上必须把合并阈值当作并行配置的输入而非事后调优项：阈值放松使序列变短，TP 的 All-Reduce 消息变小、EP 的 All-to-All 路由表变稀疏，但视觉特征重建误差上升；阈值收紧则相反。跨模态注意力近似作用于对齐层，若该层按解码侧放置并参与 TP 切分，近似误差会沿 TP 组的归约路径传导到输出分布，此时 TP 度越大，误差在归约中被平均的次数越多，单卡偏差被稀释但系统性偏移保留。</p>\n<p>通信何时成为瓶颈可以用一个可核验的判据表达。设单层计算时间为 <span class=\"inline-math\">\\(t_{\\mathrm{comp}}\\)</span>，一次集合通信的有效时间为 <span class=\"inline-math\">\\(t_{\\mathrm{comm}}=\\alpha+\\beta S\\)</span>，其中 <span class=\"inline-math\">\\(S\\)</span> 为该层需交换的字节数，<span class=\"inline-math\">\\(\\alpha\\)</span> 为固定启动开销、<span class=\"inline-math\">\\(\\beta\\)</span> 为倒数带宽。当 <span class=\"inline-math\">\\(t_{\\mathrm{comm}}/t_{\\mathrm{comp}}\\)</span> 超过约一成的量级，通信开始主导层延迟，此时继续提高 TP 度只会放大 <span class=\"inline-math\">\\(\\alpha\\)</span> 项而收益递减。NVLink 5 与 NVSwitch 降低的是 <span class=\"inline-math\">\\(\\beta\\)</span>，对 <span class=\"inline-math\">\\(\\alpha\\)</span> 无改善，因此小消息密集的 All-Reduce 在 TP 组内仍受启动开销约束；EP 的 All-to-All 则受路由不均衡影响，视觉 token 压缩后序列变短会加剧专家负载偏斜，使有效带宽低于峰值。NIXL 传输用于跨节点 KV 与视觉特征搬运，其代价体现在分离式预填/解码场景：预填侧压缩后的视觉序列越短，传输字节越少，但解码侧按压缩后长度分配的 KV cache 块必须与预填侧一致，否则回退路径无法在请求入口完成切换。</p>\n<table class=\"mini\"><thead><tr><th>切分维度</th><th>压缩带来的形状变化</th><th>主要通信代价</th><th>失效条件</th></tr></thead><tbody><tr><td>TP</td><td>跨模态注意力激活分片变小</td><td>All-Reduce 消息变小但启动开销占比升高</td><td>TP 度过大时归约延迟主导</td></tr><tr><td>EP</td><td>视觉 token 变短致专家路由稀疏</td><td>All-to-All 负载不均衡</td><td>合并阈值过松致细粒度信息丢失</td></tr><tr><td>PP</td><td>视觉编码器与解码分段边界不变</td><td>段间激活传输</td><td>压缩组合在段间不一致</td></tr><tr><td>DP</td><td>批内视觉序列长度差异扩大</td><td>梯度无关，仅批调度</td><td>长视频请求混批拖累短请求</td></tr></tbody></table>\n<p>具体到一个 GB200 NVL72 部署档位：视觉编码器量化与 token 合并联合标定后，若把长视频请求与短请求混在同一 DP 批中，KV cache 按压缩后长度分配的策略会被最长序列拉高水位，短请求的显存块被挤占，批调度被迫降低并发，吞吐下降而单请求延迟不降。正确做法是长视频请求单独成批并按帧采样控制序列长度，压缩组合在请求入口按 SLO 选定，超预算即回退保守组合——回退必须在入口完成，解码中途切换会破坏 KV cache 与并行切分的一致性。工具链以插件形式独立启停三类算子，正是为了让部署侧能按硬件档位归因显存与延迟收益，而不是把并行拓扑与压缩强度绑死在一套配置里。</p>\n<h3 id=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-39\">三十九 · 精度塌陷的归因链：从 KL 项到视觉重建误差</h3>\n<p>精度塌陷在 AngelSlim 流水线上不是单点故障，而是三项损失耦合失衡的外在表现。压缩目标函数把权重量化误差、视觉特征重建误差与输出分布 KL 三项加权求和，任何一项权重偏移都会在线上表现为可观测的精度下降。诊断的第一步是把塌陷定位到具体项：若视觉编码器量化精度被压得过低，第二项主导，表现为细粒度视觉特征（小目标、密集文字、纹理判别）先失效；若 token 合并阈值过松，视觉序列被裁得过短，跨模态注意力拿不到足够对齐依据，第三项 KL 迅速放大，表现为需要跨图比较或多步视觉推理的请求答错率上升；若仅权重量化激进而激活保持高精度，第一项可控但解码端数值漂移仍会通过 KL 传导。</p>\n<p>工程上可操作的判据是分层探针：在视觉编码器输出边界采集压缩前后的特征序列，计算逐 patch 的相对重建误差分布，而不是只看均值——均值掩盖长尾，而长尾 patch 往往正是下游答错的那部分。同时在对齐层采集压缩前后输出分布的 KL，按请求类型分桶（单图问答、多图比较、视频时序问答），因为不同请求形态对同一压缩组合的敏感度差异极大。定位顺序应遵循“先视觉、后对齐、再解码”：视觉特征重建误差是上游根因，KL 是下游症状，倒着查会把解码端的正常数值噪声误判为压缩缺陷。</p>\n<div class=\"formula\">$$\\mathcal{L}_{\\mathrm{comp}}=\\lambda_{1}\\|W-\\hat{W}\\|_{2}^{2}+\\lambda_{2}\\sum_{i}\\left\\|f_{v}(x_{i})-\\hat{f}_{v}(x_{i})\\right\\|_{2}^{2}+\\lambda_{3}\\,\\mathrm{KL}\\left(p_{\\theta}(y\\mid v,t)\\,\\|\\,p_{\\hat{\\theta}}(y\\mid \\hat{v},t)\\right)$$</div>\n<p>代价维度上，精度塌陷的诊断本身要消耗算力：逐 patch 特征采集意味着视觉编码器前向要额外保留中间激活，显存开销随视觉序列长度线性增长，长视频请求上这一开销可能挤占本已紧张的 KV cache 预算。因此探针应采样而非全量，按请求哈希抽样固定比例，并把探针开销计入监控预算而非推理预算。具体例子：一个以高分辨率文档图像为主的请求桶，在合并阈值调松一档后，特征重建误差均值几乎不变，但长尾 patch 误差抬升，对应下游表格数值抽取错误率上升——只看均值会漏掉这类塌陷。</p>\n\n<h3 id=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-40\">四十 · OOM 的三条路径与显存账本</h3>\n<p>OOM 在 Blackwell 部署上很少是单一原因，AngelSlim 场景下有三条典型路径。第一条是视觉序列长度失控：压缩后序列长度直接决定跨模态注意力与 KV cache 的显存占用，是部署容量的第一约束；当请求分辨率或帧数超出标定档位，合并模块来不及把序列压到预算内，KV cache 按压缩后长度分配时就会突破预留块。第二条是批内长度方差：长视频请求与短请求混批，批的显存需求由最长序列决定，短请求被迫为长请求的 KV cache 买单。第三条是压缩组合切换瞬间的双份驻留：回退到保守组合时若在解码中途切换，旧组合的 KV cache 与新组合的分配策略并存，瞬时显存翻倍。</p>\n<p>诊断 OOM 的关键是建立显存账本，把每请求显存拆成视觉编码器激活、压缩后视觉 token、跨模态对齐中间量、KV cache 四块，并按档位记录基线。账本的价值在于区分“容量不足”与“分配策略错误”：前者需要调压缩组合或扩容量，后者只需修批调度。伪代码思路是请求入口处先按 patch 数估算视觉 token 上界，再按压缩组合的标定压缩比推算 KV cache 需求，超预算请求直接路由到保守组合或单独成批，而不是等分配失败再补救。</p>\n<table class=\"mini\"><thead><tr><th>OOM 路径</th><th>可观测信号</th><th>定位手段</th><th>代价</th></tr></thead><tbody><tr><td>视觉序列超预算</td><td>KV cache 分配失败集中于高分辨率/长视频桶</td><td>按 patch 数分桶统计失败率</td><td>容量受限，需降档或扩显存</td></tr><tr><td>批内长度方差</td><td>失败率随批内最长序列长度上升</td><td>批组成回放，对比长短分离批</td><td>长短分离降低批利用率，吞吐下降</td></tr><tr><td>切换双份驻留</td><td>回退时刻附近失败率尖峰</td><td>入口切换日志与分配时间线对齐</td><td>入口切换增加排队延迟</td></tr></tbody></table>\n<p>具体例子：视频请求按帧采样控制序列长度，若采样策略在入口处未与压缩组合联动，同一请求在保守组合下能过、在激进组合下 OOM，表现为“同一请求时好时坏”的伪随机失败。把帧采样与组合选择绑定在入口决策里，这类失败即可归因消除。</p>\n\n<h3 id=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-41\">四十一 · 批抖动与尾延迟：调度层的可观测性</h3>\n<p>批抖动指批组成在相邻调度周期之间剧烈变化，导致吞吐与延迟同时劣化。AngelSlim 的压缩组合按 SLO 延迟预算选择，线上超预算时回退保守组合，而回退路径需在请求入口完成——这意味着组合切换会改变请求的预计服务时长，进而改变调度器对批的打包决策。若调度器不知道组合已切换，仍按旧组合的时长估计打包，就会出现批内请求时长方差放大、批完成时间被最长请求拖住、后续批被迫等待的连锁反应。尾延迟的典型形态是 P99 抬升而 P50 平稳：大部分请求在新组合下更快，少数回退请求拖长了整批。</p>\n<p>诊断批抖动需要三个观测面：批组成的时间序列（批大小、批内序列长度分布、组合标签分布）、批完成时间的分解（视觉编码、对齐、解码各段耗时）、以及回退事件与批边界的时间对齐。判据是：若尾延迟尖峰与回退事件在时间上重合，问题在切换策略；若尖峰与批内最长序列长度相关而与回退无关，问题在打包策略。前者应把组合决策前移到请求入口并让调度器读取组合标签，后者应对长序列请求单独成批。</p>\n<div class=\"formula\">$$T_{\\mathrm{batch}}\\approx \\max_{r\\in B}\\left(T^{\\mathrm{vis}}_{r}+T^{\\mathrm{align}}_{r}+T^{\\mathrm{dec}}_{r}\\right),\\quad \\mathrm{P99}\\ \\text{由}\\ \\max\\ \\text{项主导}$$</div>\n<p>代价上，批抖动直接吃掉压缩收益：压缩把单请求时长降下来，但批完成时间由最长请求决定，若长短混批，压缩带来的平均收益无法转化为吞吐。具体例子：一个以短问答为主的请求流中混入少量长视频请求，长视频在激进组合下仍超出延迟预算而回退，回退请求的解码段变长，整批完成时间被拉长，短请求的 P99 随之抬升——此时应做的是入口分流而非继续调压缩阈值。</p>\n\n<h3 id=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-42\">四十二 · 静默降级：接口一致性的双刃剑</h3>\n<p>静默降级是 AngelSlim 最危险的失败模式，根源恰是其设计优点：压缩前后模型接口保持一致，部署侧可按请求切换组合而不改调用方。接口一致意味着调用方无法从返回结构上察觉组合已切换，若监控只覆盖服务可用性与返回码，精度下降会以“服务正常但答案变差”的形式静默发生。三类静默降级值得单独设防：合并阈值过紧导致的细粒度信息丢失、跨模态注意力近似误差传导到解码输出分布、以及量化精度在特定输入分布上越界。</p>\n<p>监控静默降级不能依赖单请求延迟或显存指标，必须建立输出侧的质量代理。可行手段包括：对固定探针集周期性跑压缩前后输出的一致性比对（分布距离或答案一致率），按请求桶分别统计；对高风险桶（文档抽取、密集文字、多图比较）设置更严的一致性阈值；把压缩组合标签写入请求追踪，使任何质量回归都能回溯到具体组合。定位时先看组合标签分布是否发生漂移——若某桶的请求被大量路由到保守组合，说明激进组合在该桶上已被回退机制隐性判定为不合格，这本身就是精度塌陷的早期信号。</p>\n<p>代价维度：探针集比对要占用推理容量，且探针请求的视觉序列长度若与真实流量不符，比对结论会失真。工程判断是把探针集按真实请求桶的序列长度分布采样，并把比对频率与组合切换频率挂钩——切换越频繁，比对越密。具体例子：跨模态注意力近似在对齐层生效，近似误差会传导到解码输出分布，表现为需要精确引用图像局部内容的请求答错，而普通描述类请求无异常；若探针集只含描述类请求，这类降级不会被发现。</p>\n\n<h3 id=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-43\">四十三 · 回滚路径与诊断闭环</h3>\n<p>回滚不是把组合换回去就结束，而是要保证 KV cache 一致性与批边界干净。压缩组合切换需在请求入口完成，解码中途切换会破坏 KV cache 一致性——旧组合按压缩后长度分配的块与新组合的分配策略不匹配，已写入的 KV 无法安全复用。因此回滚的正确形态是：入口决策层维护组合状态机，切换只对新请求生效，在途请求按原组合跑完；回退触发条件由延迟预算与质量探针共同决定，任一越界即锁定保守组合一段时间，避免在边界上反复抖动。</p>\n<p>诊断闭环的最小构成是：指标采集（每请求延迟、显存、组合标签、质量探针结果）→ 归因（按桶与组合交叉分析）→ 决策（调阈值、调组合、改批策略）→ 验证（探针集与线上桶指标对比）。闭环的关键是把“压缩收益归因”做成常态能力：量化、合并与注意力近似可独立启停，插件式挂载使每次只变一个变量，从而把显存与延迟收益精确归到具体步骤，而不是笼统归给“压缩”。</p>\n<ul><li>回滚触发：延迟超预算或质量探针越界，二者取或，锁定保守组合。</li><li>在途保护：切换只对新请求生效，在途请求跑完原组合，避免 KV cache 不一致。</li><li>归因纪律：单变量启停，按桶记录显存与延迟代理指标，供部署侧回放选择。</li><li>抖动抑制：回退后设冷却窗口，防止组合在预算边界反复切换放大批抖动。</li></ul>\n<p>具体例子：某硬件档位上激进组合在长视频桶触发延迟回退，回退后短请求桶的 P99 反而改善——这说明原批组成被长视频污染，正确处置是长视频单独成批并保留激进组合，而不是全局回退保守组合。回滚策略若一刀切，会把局部失败放大为全局吞吐损失。最后落在工程判断上：AngelSlim 的失败模式诊断应以请求桶为单位、以组合标签为索引、以单变量启停为纪律，把精度塌陷、OOM、批抖动、尾延迟与静默降级统一到同一套可回放的指标账本里，任何无法归因到具体压缩步骤的收益或损失都不应进入部署决策。</p>\n<h3 id=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-44\">四十四 · 口径先于数字：AngelSlim 的测量坐标系</h3>\n<p>AngelSlim 的材料里没有任何可核验的吞吐、延迟或精度数字，这不是缺陷，而是这套工具链的性质决定的：它交付的是<strong>可组合的压缩入口</strong>，不是一份排行榜成绩。因此读它的“基准”必须先读口径——压缩组合是按硬件档位与 SLO 预算选出来的，同一份模型在 B200、B300、GB200 NVL72 上挂的是不同插件组合，任何跨档位的数字直接相减都失去意义。工具链在离线阶段为每个档位选定量化与合并组合，线上按 SLO 切换并采集延迟与显存指标；这意味着“基准”本身是一个随部署档位变化的函数，而不是一个常量。工程上正确的读法是：先固定档位、固定压缩组合、固定请求形态，再看指标；三者任一变动，数字即不可比。</p>\n<p>更具体地说，AngelSlim 的插件挂在五段边界上——输入预处理、视觉编码器、token 压缩与合并、跨模态注意力、语言解码。量化作用于权重与激活，合并作用于视觉序列，近似作用于对齐层。每一类算子改变的是不同段的代价结构：视觉编码器量化改变的是编码器前向的计算与带宽，token 合并改变的是跨模态注意力与 KV cache 的显存占用，注意力近似改变的是对齐层的计算路径与输出分布。把三类收益加总成一个“加速比”是口径错误，因为它们的代价落在不同资源上，且相互耦合——合并强度越高，量化误差对视觉特征重建的影响越被放大。</p>\n<div class=\"formula\">$$\\mathcal{L}_{\\mathrm{comp}}=\\lambda_{1}\\|W-\\hat{W}\\|_{2}^{2}+\\lambda_{2}\\sum_{i}\\left\\|f_{v}(x_{i})-\\hat{f}_{v}(x_{i})\\right\\|_{2}^{2}+\\lambda_{3}\\,\\mathrm{KL}\\left(p_{\\theta}(y\\mid v,t)\\,\\|\\,p_{\\hat{\\theta}}(y\\mid \\hat{v},t)\\right)$$</div>\n<p>这个损失三项分别对应权重量化误差、视觉特征重建误差与输出分布 KL。它本身就是口径声明：三项加权意味着压缩不是单目标优化，任何只报其中一项的“提升”都是不完整的。校准数据驱动量化与合并参数的联合搜索，因此基准必须声明校准集与目标档位，否则复现无从谈起。</p>\n\n<h3 id=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-45\">四十五 · 硬件档位与 batch：容量第一约束来自视觉序列长度</h3>\n<p>在 Blackwell 上，多模态推理同时受视觉编码器计算、视觉 token 数量与量化误差三重约束。AngelSlim 把视觉 token 压缩挂在视觉编码器输出边界，压缩后的序列长度直接决定跨模态注意力与 KV cache 的显存占用——这是部署容量的第一约束，先于 batch 大小。换句话说，batch 不是自由变量：它被压缩后序列长度反推出来。按 patch 数估计显存是唯一可靠的起点，分辨率与帧数增长直接抬升序列长度，KV cache 随之膨胀。</p>\n<p>批调度的口径因此有两层。第一层是静态容量：给定档位的显存上限、给定压缩组合下的每 token KV 占用，算出单请求可容纳的序列长度与并发上限。第二层是动态分层：并发按 SLO 延迟预算分层，压缩组合切换必须在请求入口完成。长视频请求应单独成批，避免 KV cache 随帧数线性膨胀拖累短请求批——这是混合批里最典型的不可比来源：一个含长视频的批与一个纯短请求的批，其 TPOT 与吞吐数字放在一起比较毫无意义。视频输入还需按帧采样策略控制序列长度，帧采样率是口径的一部分，不声明采样率的长视频基准不可复现。</p>\n<table class=\"mini\"><thead><tr><th>口径维度</th><th>必须声明的内容</th><th>不声明时的后果</th></tr></thead><tbody><tr><td>硬件档位</td><td>B200 / B300 / GB200 NVL72，及对应压缩组合</td><td>跨档位数字相减，收益归因失效</td></tr><tr><td>batch 构成</td><td>是否混入长视频请求、帧采样率</td><td>TPOT 与吞吐被长序列拖尾污染</td></tr><tr><td>压缩组合</td><td>量化精度、合并阈值、近似开关</td><td>无法区分是合并还是量化带来收益</td></tr><tr><td>并发分层</td><td>SLO 延迟预算与回退策略</td><td>高并发下的回退被误读为性能下降</td></tr></tbody></table>\n<p>工程代价在这里体现得很直接：合并阈值过松会损失细粒度视觉信息，过紧则压缩收益不足以抵消合并本身的开销。合并开销落在视觉编码器输出边界，是串行路径上的一段，它不随 batch 增大而摊薄，因此在小 batch、低并发场景下，合并的净收益可能为负。这是基准里最容易被忽略的一项：压缩不是免费的，合并本身有延迟成本。</p>\n\n<h3 id=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-46\">四十六 · 指标怎么读：TTFT、TPOT、吞吐、显存、功耗各自归谁</h3>\n<p>TTFT 在 AngelSlim 的流水线里由三段构成：预处理与 patch 切分、视觉编码器前向、跨模态注意力对齐。视觉编码器量化直接作用于第二段，是 TTFT 的主要杠杆；token 合并作用于第二段与第三段之间，缩短的是对齐层的输入长度，对 TTFT 的贡献取决于对齐层在总时延中的占比。TPOT 则主要落在语言解码段，受 KV cache 长度与批调度影响，压缩后序列长度缩短会降低每步注意力的显存读取量，从而改善 TPOT——但这一收益只在解码段占主导时才显现。</p>\n<p>吞吐的口径最容易被误用。连续批处理下，吞吐由每步可容纳的请求数与每请求的解码步数共同决定；压缩组合切换在请求入口完成，意味着同一时刻批内可能混有不同组合的请求，此时吞吐是混合口径，不能与单一组合的吞吐直接比较。显存的口径要区分峰值与稳态：KV cache 按压缩后长度分配，长视频请求预留更大显存块，峰值显存由最长请求决定，稳态显存由并发分层决定。功耗在材料中未被量化，只能定性地说：视觉编码器量化降低的是计算与带宽，合并降低的是注意力负载，两者对功耗的贡献路径不同，不可合并成一个“能效提升”。</p>\n<ul>\n<li>TTFT：视觉编码器量化是主杠杆，合并的贡献取决于对齐层占比。</li>\n<li>TPOT：由 KV cache 长度与批调度决定，压缩后序列缩短改善显存读取。</li>\n<li>吞吐：混合组合批下为混合口径，不可与单组合吞吐直接比较。</li>\n<li>显存：峰值由最长请求决定，稳态由并发分层决定。</li>\n<li>功耗：材料未量化，量化与合并的贡献路径不同，不可合并表述。</li>\n</ul>\n<p>一个具体例子：同一张高分辨率图像，在未压缩组合下视觉序列长度大，KV cache 分配块大，单批可容纳请求数少，TTFT 受编码器计算主导；切换到量化加合并组合后，序列缩短，KV cache 块变小，单批请求数上升，吞吐改善，但合并开销进入串行路径，TTFT 的改善幅度取决于编码器量化节省是否大于合并开销。这两个数字必须在同一档位、同一 SLO 下成对报告，否则读者无法判断净收益方向。</p>\n\n<h3 id=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-47\">四十七 · 哪些提升不可比：四类典型陷阱</h3>\n<p>第一类不可比是跨档位。B200、B300、GB200 NVL72 的压缩组合随档位切换，量化精度与合并强度在离线阶段已按档位选定。把 B200 上的压缩收益直接搬到 GB200 NVL72 上引用，等于假设组合不变，而事实是组合随档位变化。第二类不可比是跨请求形态：长视频与短请求混批时，KV cache 随帧数线性膨胀，拖累整批 TPOT，此时测得的吞吐是混合负载的吞吐，不代表纯短请求场景。</p>\n<p>第三类不可比是跨压缩组合的加总。量化、合并与注意力近似可独立启停，便于按硬件档位归因显存与延迟收益——但“独立启停”不等于“收益可加”。视觉特征重建误差与输出分布 KL 在损失里是加权耦合的，合并强度改变视觉序列，量化误差在缩短后的序列上被放大，两者联合标定才有意义；单独调优易高估收益。第四类不可比是回退路径的误读：线上超预算触发回退保守组合，回退在请求入口完成以避免解码中途切换破坏 KV cache 一致性。监控里看到的延迟尖峰可能是回退事件，而非组合本身变慢；把回退后的保守组合指标当作主组合指标，是口径混淆。</p>\n<div class=\"formula\">$$\\text{净收益}=\\underbrace{\\Delta T_{\\text{enc}}}_{\\text{量化节省}}-\\underbrace{T_{\\text{merge}}}_{\\text{合并开销}}-\\underbrace{\\Delta T_{\\text{attn}}}_{\\text{近似误差传导}}$$</div>\n<p>这个式子只作定性框架：三项符号与量级需在档位上实测。它说明为什么单报“压缩后序列缩短 X%”不构成收益证据——序列缩短只进入第三项的分母，前两项的符号决定净收益方向。跨模态注意力近似的误差会传导到解码输出分布，精度口径必须与延迟口径同时给出，否则“更快”可能只是“更不准”的同义词。</p>\n\n<h3 id=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-48\">四十八 · 可核验的读法：把基准写成可回放的配置</h3>\n<p>既然材料未给出数据集、基线与数字，唯一可核验的读法是要求基准以<strong>配置</strong>形式给出，而非以<strong>结果</strong>形式给出。一份可回放的 AngelSlim 基准应包含：硬件档位、压缩组合（量化精度、合并阈值、近似开关）、校准数据来源、请求形态（分辨率、帧采样率、长短请求比例）、并发分层与 SLO 预算、回退策略。缺任一项，数字即不可比。工具链在离线阶段记录每步的显存与延迟代理指标供部署侧回放选择，这正是把基准写成配置的机制基础——代理指标不是最终指标，但它是可回放的锚点。</p>\n<p>工程判断上，AngelSlim 的基准价值不在“快了多少”，而在“归因是否成立”。三类压缩步骤挂在各段边界，接口与未压缩模型保持一致，部署侧可按请求切换组合；这使得同一请求在不同组合下的延迟与显存可以被逐段拆解，而不是被一个端到端数字掩盖。代价是测量复杂度上升：需要按段采集、按组合分层、按请求形态分组。对于有工程背景的读者，正确的动作是把这套分段口径固化进压测脚本，让每个数字都带着档位、组合与请求形态的标签，任何脱离标签的引用都应被视为不可比。</p>\n<p>最后落在具体机制上：压缩组合切换在请求入口完成，回退路径同样在入口判定，这意味着基准的采样点必须对齐请求边界，而不是解码步边界。若监控按解码步采样，回退事件会被切碎成若干步的延迟抖动，无法还原为一次组合切换。把采样点钉在请求入口、把标签钉在组合与档位上，是 AngelSlim 基准可读的最小工程条件。</p>\n\n<h3 id=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-49\">四十九 · 基准口径与不可比边界：压缩收益怎么读</h3>\n<p>AngelSlim 的收益读数必须绑定四个坐标：硬件档位（B200、B300、GB200 NVL72）、压缩组合（视觉编码器精度 × token 合并阈值 × 跨模态注意力近似开关）、批与并发形态、指标口径。材料未给出数据集、基线、吞吐与精度数字，因此任何“提升 X 倍”的说法都只能作为实测待验项。可核验的只有结构性事实：视觉 token 合并挂在编码器输出边界，压缩后序列长度 <em>L</em><sub>v</sub>′ 直接决定跨模态注意力负载与 KV cache 占用，是部署容量的第一约束。容量估算可按 <div class=\"formula\">$$M_{\\mathrm{KV}} \\approx 2 \\cdot L_{v}' \\cdot d \\cdot b \\cdot s \\cdot \\text{bytes}$$</div> 其中 <em>b</em> 为层数、<em>s</em> 为并发序列数；合并阈值调松使 <em>L</em><sub>v</sub>′ 下降，显存收益近似线性，但细粒度视觉信息损失不可由该式体现。</p>\n<p>指标之间不可横向换算。TTFT 受视觉编码器前向与预处理切 patch 主导，TPOT 受解码批调度与 KV 读取带宽主导，吞吐受批内视觉序列长度方差主导。同一组合在短图像、高并发下吞吐提升显著，在长视频、低并发下单请求延迟可能反而变差——长视频按帧采样后序列仍长，合并开销与跨模态对齐开销叠加。因此比较两个组合时必须固定请求分布与并发分层，否则数字不可比。功耗维度同理：量化降低的是权重带宽与算力占用，不等于整机功耗同比下降，视觉编码器与解码器分离部署时功耗归因需按段拆分。</p>\n<p>失效条件集中在三处。其一，压缩组合切换必须在请求入口完成，解码中途切换会破坏 KV cache 与压缩后序列长度的一致性，回退路径要前置到调度层。其二，token 合并阈值与量化精度需联合标定：单独调阈值会高估收益，因为量化误差与特征重建误差在 <div class=\"formula\">$$\\mathcal{L}_{\\mathrm{comp}}=\\lambda_{1}\\|W-\\hat{W}\\|_{2}^{2}+\\lambda_{2}\\sum_{i}\\left\\|f_{v}(x_{i})-\\hat{f}_{v}(x_{i})\\right\\|_{2}^{2}+\\lambda_{3}\\,\\mathrm{KL}\\left(p_{\\theta}(y\\mid v,t)\\,\\|\\,p_{\\hat{\\theta}}(y\\mid \\hat{v},t)\\right)$$</div> 中通过 KL 项耦合，合并改变 <em>v</em> 的分布，量化误差对输出的传导随之变化。其三，跨模态注意力近似的精度损失边界材料未给出实测结论，近似误差会经对齐层传导到解码输出分布，短回答任务上不易暴露，长文本生成与细粒度视觉问答上风险更高。</p>\n<table class=\"mini\"><thead><tr><th>读数场景</th><th>可比性判断</th><th>工程代价落点</th></tr></thead><tbody><tr><td>同档位、同请求分布、仅换合并阈值</td><td>可比，显存收益可归因</td><td>合并开销抵消部分延迟收益</td></tr><tr><td>跨档位（B200 对 GB200 NVL72）</td><td>不可比，并行拓扑与通信占比不同</td><td>跨模态层随解码侧放置，通信延迟入 TTFT</td></tr><tr><td>长视频与短图像混批</td><td>不可比，批内序列方差污染吞吐</td><td>KV cache 随帧数膨胀，短请求被拖累</td></tr></tbody></table>\n<p>工程判断落在回放机制上：工具链离线阶段为每个硬件档位记录每步显存与延迟代理指标，线上按 SLO 切换组合并采集每请求延迟与显存占用，超预算即回退保守组合。这套机制的价值不在单点数字，而在把视觉编码器延迟、视觉 token 显存与量化误差放进同一条可核验流水线归因；没有基线数字时，唯一可靠的读法是看回退触发率与组合切换频次——触发频繁说明所选组合在该请求分布下已越出延迟预算，收益口径应重新标定。</p>\n<h3 id=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-50\">五十 · 迁移到新视觉骨干：压缩插件的挂载点会变，误差项权重必须重标</h3>\n<p>AngelSlim 的五段结构（预处理、视觉编码器、token 压缩与合并、跨模态注意力、语言解码）在接口层面是稳定的，但迁移到另一种视觉骨干时，真正要改的不是插件代码，而是插件的挂载位置与损失权重。以 ViT 类骨干为例，token 合并挂在编码器输出边界是自然的，因为 patch 序列在编码器末端已经是语义特征；若换成带层级下采样的骨干（如多尺度卷积—注意力混合结构），序列长度在编码器内部就已逐级收缩，把合并算子继续挂在末端等于在已经压缩过的序列上二次裁剪，收益被前置下采样吃掉，而合并开销照付。工程判断是：合并插件应前移到“序列长度尚未被骨干自身压缩”的那一段边界，否则阈值调参会系统性高估收益。</p>\n<p>量化插件的迁移代价更隐蔽。视觉编码器量化以权重与激活为对象，损失函数中第二项是视觉特征重建误差：</p>\n<div class=\"formula\">$$\\mathcal{L}_{\\mathrm{comp}}=\\lambda_{1}\\|W-\\hat{W}\\|_{2}^{2}+\\lambda_{2}\\sum_{i}\\left\\|f_{v}(x_{i})-\\hat{f}_{v}(x_{i})\\right\\|_{2}^{2}+\\lambda_{3}\\,\\mathrm{KL}\\left(p_{\\theta}(y\\mid v,t)\\,\\|\\,p_{\\hat{\\theta}}(y\\mid \\hat{v},t)\\right)$$</div>\n<p>换骨干意味着 $f_v$ 的特征分布变了——通道方差、激活离群值位置、层间残差幅度都不同。原档位上标定出的 $\\lambda_2$ 与 $\\lambda_3$ 比例不再成立：若新骨干激活离群值更集中，$\\lambda_1$ 需要上调以压制权重量化误差向特征层的传导；若新骨干特征重建本身就更脆弱（例如浅层特征被直接送入跨模态对齐），$\\lambda_3$ 需要上调以约束输出分布漂移。这不是调参玄学，而是可操作的流程：在新骨干上跑一遍校准集，分别固定两组权重、扫描第三组，观察三项损失的量级比，再决定权重。代价体现在离线标定工时与部署侧的精度回归测试上，而非线上延迟。</p>\n<p>具体例子：把一个在 B200 档位上以 FP8 视觉编码器 + 中等合并阈值标定好的组合，直接搬到 GB200 NVL72 上另一种骨干，若不做重标，典型表现是视觉特征重建误差在浅层放大、跨模态对齐层的注意力熵异常升高，解码输出在细粒度视觉问答上退化，而延迟指标看起来“正常”——这正是归因失效的典型场景。</p>\n\n<h3 id=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-51\">五十一 · 跨领域迁移：视频与长序列是容量约束的真正上限</h3>\n<p>图像请求的视觉序列长度由分辨率与 patch 数决定，量级可控；视频请求的序列长度随帧数线性增长，压缩后序列长度直接决定跨模态注意力与 KV cache 的显存占用，是部署容量的第一约束。迁移到视频领域时，AngelSlim 的合并插件本身不需要改接口，但帧采样策略必须与合并阈值联合设计：帧采样决定进入编码器的帧数，合并阈值决定每帧保留的 token 数，两者相乘才是 KV cache 的分配依据。若只调其中一个，容量估算会失真。</p>\n<p>批调度层面的边界更硬。长视频请求应单独成批，避免 KV cache 随帧数线性膨胀拖累短请求批——这是连续批处理在混合负载下的基本判断，但在 AngelSlim 的组合切换语义下多了一层约束：压缩组合的切换必须在请求入口完成，解码中途切换会破坏 KV cache 一致性。因此视频请求的档位选择发生在它进入批次之前，一旦入批就锁定组合，回退只能作用于后续请求。工程上这意味着调度器需要按“请求类别 + 预估序列长度”做准入分组，而不是按到达顺序贪心拼批。</p>\n<p>代价可以定性估算：设单帧压缩后保留 $k$ 个视觉 token、采样 $F$ 帧、批内并发 $B$，则视觉侧 KV 占用近似正比于 $B \\cdot F \\cdot k \\cdot d \\cdot L$（$d$ 为隐藏维、$L$ 为层数）。合并阈值过松使 $k$ 上升，帧采样过密使 $F$ 上升，二者叠加会把显存预算击穿，而此时视觉编码器计算量并未同比例下降——编码器仍要处理全部采样帧。这就是视频领域迁移时“省了注意力、没省编码器”的典型失衡，也是判断该方案是否适用的分水岭：若负载以高帧率长视频为主，视觉编码器计算而非 KV cache 才是瓶颈，AngelSlim 的合并与注意力近似收益会被编码器前向时间掩盖。</p>\n\n<h3 id=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-52\">五十二 · 跨模态注意力近似的适用边界：对齐层不是任意层</h3>\n<p>跨模态注意力近似作用于对齐层，压缩前后接口一致使部署侧可按请求切换组合，但近似误差会传导到解码输出分布。迁移到新领域时，最需要判断的是“对齐层在哪里、有几层”。在浅层对齐结构（视觉特征经少量 cross-attention 层注入解码器）中，近似误差集中且可被 $\\lambda_3$ 约束；在深层交织结构（视觉 token 与文本 token 在多层级联融合）中，近似误差会逐层累积，KL 项在单层标定下低估了总漂移。判断规则：对齐层数越多，近似应越保守，甚至只对末层对齐做近似，把前面的对齐层保持精确——因为前面层的误差会被后续层放大，而末层误差直接进入输出分布，反而更容易被 KL 项捕获和约束。</p>\n<p>另一个边界是任务形态。以细粒度空间定位、小目标计数、密集文字识别为主的请求，视觉 token 合并的相似度阈值过松会直接损失细粒度视觉信息，此时压缩收益不足以抵消合并开销，且精度退化不可通过解码侧补偿。这类负载应走保守组合甚至不压缩路径，把容量预算留给 KV cache 而非压缩比。反之，以整体场景描述、粗粒度分类为主的请求，合并阈值可以放宽，近似误差对输出分布的影响被任务本身的低敏感性吸收。</p>\n<p>代价侧要看清一点：跨模态注意力近似的收益主要体现在对齐层的注意力计算与中间激活显存上，对解码阶段的逐 token 生成延迟影响有限。若 SLO 瓶颈在解码 token 间隔而非预填阶段，这项近似的投入产出比最低，应优先保证量化与合并的正确性。</p>\n\n<h3 id=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-53\">五十三 · 规模上限：三处硬约束决定这套方案能走多远</h3>\n<p>第一处是视觉编码器计算。合并与注意力近似都不减少编码器前向的 FLOPs，编码器延迟随分辨率与帧数增长，是预填阶段的下界。当请求的视觉输入规模上升时，编码器时间占比上升，压缩带来的解码侧收益被稀释。规模上限的判断标准是：编码器前向时间是否已超过 SLO 预填预算的主要部分；若是，则该档位下 AngelSlim 的压缩组合只能解决显存问题，解决不了延迟问题。</p>\n<p>第二处是合并开销与收益的交叉点。视觉 token 合并按相似度阈值裁剪序列，阈值过紧则压缩收益不足以抵消合并开销——合并本身要做相似度计算与重排，这部分计算随序列长度增长。存在一个序列长度区间，低于它合并净收益为负；高于它净收益转正。迁移到新模型时这个交叉点会移动，因为相似度计算的成本取决于特征维与实现，裁剪收益取决于后续注意力与 KV 的节省比例。工程上应把交叉点作为档位选择的判据之一，而不是默认“压缩总是划算”。</p>\n<p>第三处是量化精度的下限。视觉编码器与解码器可分别设定精度，但精度选择与 token 合并强度共同决定视觉特征重建误差，需在部署档位上联合标定。单独调优易高估收益：把量化精度压到很低、合并阈值放得很松，两项误差在特征层叠加，KL 项约束不住，输出分布漂移超出可接受范围。规模上限在此表现为“压缩比—精度”的可行域边界，越过边界的组合在离线标定阶段就应被剔除，而不是留给线上回退兜底。</p>\n<p>三处约束共同给出判断：AngelSlim 适用于视觉输入规模中等、解码侧显存与注意力计算为主要瓶颈、且任务对细粒度视觉信息敏感度可控的负载；不适用于编码器计算主导延迟的超高分辨率或高帧率场景，也不适用于对齐层深且任务精度要求苛刻的场景。</p>\n\n<h3 id=\"paper-angelslim-a-more-accessible-comprehe-2026-sec-54\">五十四 · 迁移检查清单与不可迁移的部分</h3>\n<p>可迁移的是接口契约：压缩前后模型接口保持一致，插件以独立启停形式挂载，量化、合并与注意力近似可分别归因显存与延迟收益。这套契约在新模型上仍然成立，迁移工作量集中在标定而非重构。不可迁移的是三样东西：一是原档位上的损失权重比例，换骨干必须重标；二是原负载下的合并阈值，换领域（图像到视频、通用到细粒度）必须重扫；三是原 SLO 下的组合选择表，换硬件档位（B200 到 B300、单机到 GB200 NVL72）必须重测，因为并行拓扑按视觉编码器与语言解码分离部署、跨模态注意力层随解码侧放置，拓扑变化会改变各段的实际耗时占比。</p>\n<p>迁移检查清单按顺序执行：先确认新骨干的序列收缩发生在哪一段，据此决定合并插件的挂载边界；再在新骨干上重标 $\\lambda_1,\\lambda_2,\\lambda_3$，以三项损失量级比为判据；然后按新领域的帧采样或分辨率策略重扫合并阈值，测出合并净收益交叉点；接着在目标硬件档位上重跑组合选择，记录每步显存与延迟代理指标；最后验证回退路径在请求入口完成切换、解码中途不切换，并确认长序列请求单独成批。</p>\n<p>监控采集每请求延迟与显存占用、超预算触发组合回退，这条链路在迁移后仍是归因的唯一依据。材料未给出失败模式与监控指标的量化结论，因此迁移后的第一轮部署应以保守组合起步，用实测数据逐步放宽，而不是直接套用原档位的激进组合。跨模态注意力近似的精度损失边界缺少实测结论，迁移到新领域时应默认关闭该近似，待 KL 项在目标负载上稳定后再启用。</p>\n<p>最终落在工程判断上：这套工具链的价值不在于某个固定压缩比，而在于把“挂载点—损失权重—阈值—档位—回退”五件事串成可核验的链条；迁移时改动的是链条上的参数，不是链条本身。判断一个迁移是否成功，看的是三项损失在新骨干上的量级比是否可解释、合并净收益交叉点是否被实测定位、以及回退路径是否在请求入口而非解码中途生效——这三点成立，压缩收益才可归因；任一点缺失，收益数字就只是噪声。</p>\n<figure class=\"diagram\" data-fig=\"paper-family\"><svg style=\"max-width:746px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 746.0 138\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><text x=\"136.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">上游 · 站在谁肩上</text><rect x=\"38.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><text x=\"48.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#b45309\" font-weight=\"500\" text-anchor=\"start\">领域入口（无上游）</text><text x=\"380.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">本文</text><rect x=\"282.0\" y=\"44.0\" width=\"196.0\" height=\"52.0\" rx=\"6\" fill=\"#e9eff5\" stroke=\"#d6e2ec\" stroke-width=\"1.2\"/><text x=\"292.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">AngelSlim: A more </text><text x=\"292.0\" y=\"78.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">accessible, comprehen…</text><text x=\"624.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">下游 · 被谁接走</text><rect x=\"526.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><text x=\"536.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#15803d\" font-weight=\"500\" text-anchor=\"start\">暂无下游记录</text><line x1=\"238.0\" y1=\"74.0\" x2=\"271.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 270.0 69.5 L 270.0 78.5 L 278.0 74.0 Z\" fill=\"#d8d3c6\"/><line x1=\"482.0\" y1=\"74.0\" x2=\"515.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 514.0 69.5 L 514.0 78.5 L 522.0 74.0 Z\" fill=\"#d8d3c6\"/><text x=\"380.0\" y=\"128.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.0\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"middle\">2026 · arXiv preprint</text></svg><figcaption><b>家谱</b> · AngelSlim: A more acces… 的上游问题、本文位置与下游继承；箭头表示方法/问题的传递，不是时间先后。</figcaption></figure>\n<table class=\"mini\" data-fig=\"paper-exp\"><caption>实验速查：这篇论文拿什么数据、和谁比、提升来自哪里</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>数据集</td><td>材料未给出具体数据集名称</td></tr><tr><td>基线</td><td>材料未给出具体基线系统</td></tr><tr><td>主要结果</td><td>材料未给出可核验的吞吐、延迟或精度数字；论文卡仅能确认工具链覆盖视觉编码器…</td></tr><tr><td>消融</td><td>材料未给出消融实验；仅可确认三类压缩步骤可独立挂载，组合选择由部署档位与 …</td></tr><tr><td>局限</td><td>材料未给出失败模式与监控指标的量化结论；工具链对视频长序列的批调度与 KV…</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：papers/paper-angelslim-a-more-accessible-comprehe-2026 · 共 9 个片段</p>\n";break;}}})();
